insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('black-friday-cart-pause-and-spending-cap-sheet', 'Black Friday Cart Pause and Spending Cap Sheet', 'worksheet'::resource_kind, 'A planning sheet for a client who overspends in holiday sales and regrets it by Monday.', 'Use it to set a cap and a pause rule before the deals start, so the decision is made calmly in advance.', array['Adults']::text[], '20 minutes before the sale weekend', 'Holiday sales are built to rush a decision, and the client who regrets November every December usually has no plan, only resolve. The sheet asks for a dollar cap, the three things they actually need, a pause rule (an item sits in the cart overnight before it is bought), and what the rush feels like in the body so they can spot it. Keep it practical rather than moralizing; the point is a plan, not a lecture about money. Watch for the client who sets a cap so low it is a setup for failure; negotiate one they can keep.', '[{"id": "f0", "type": "textarea", "label": "My spending cap for the sale weekend, and where that number came from:"}, {"id": "f1", "type": "textarea", "label": "The two or three things I actually need or planned to buy:"}, {"id": "f2", "type": "textarea", "label": "My pause rule: how long an item waits in the cart before I decide:"}, {"id": "f3", "type": "textarea", "label": "What the rush to buy feels like in my body, so I can notice it:"}, {"id": "f4", "type": "textarea", "label": "The person I will text before any purchase over my cap:"}, {"id": "f5", "type": "textarea", "label": "How I want to feel about this weekend on Monday morning:"}]'::jsonb, array['money', 'decisions', 'planning']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('first-snow-commute-leave-time-planning-sheet', 'First Snow Commute Leave Time Planning Sheet', 'worksheet'::resource_kind, 'A planning sheet for a client whose first icy commute of the year turns into a morning of panic and lateness.', 'Use it to work out a leave time, a backup route and a calm start so the first snow day is boring instead of frantic.', array['Adults']::text[], '15 minutes the evening before', 'The first snow of the season catches most people off guard, and the client who already runs anxious about being late can lose the whole morning to it. The sheet asks for the forecast, the usual commute time and a realistic snow multiplier, the leave time that follows, what gets done the night before (scraper in the car, clothes out), and a backup if the road is bad. Keep the plan light; it is one morning. Watch for the client who plans to leave two hours early and then sits in the parking lot stewing; that is anxiety dressed as planning.', '[{"id": "f0", "type": "textarea", "label": "Tomorrow''s forecast and when the snow is expected:"}, {"id": "f1", "type": "textarea", "label": "My usual commute time, and a realistic time for a snowy day:"}, {"id": "f2", "type": "textarea", "label": "The time I will leave, and what has to be done the night before to make that possible:"}, {"id": "f3", "type": "textarea", "label": "My backup route or backup plan if the road is bad:"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself if I am still late despite the plan:"}]'::jsonb, array['planning', 'stress', 'routines']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('year-end-review-self-summary-prep-sheet', 'Year-End Review Self-Summary Prep Sheet', 'worksheet'::resource_kind, 'A prep sheet for a client facing a year-end work review who cannot remember anything they did right.', 'Use it to gather the year''s real contributions and one honest growth area before the client sits down with their manager.', array['Adults']::text[], '45 minutes, a week before the review', 'Reviews bring out the client''s worst memory for their own work; they recall the missed deadline in March and nothing else. The sheet walks through the year a quarter at a time, asks for one contribution each, a problem they solved, a colleague who would vouch for them, and one area they want to grow, phrased as a plan rather than a confession. Have the client bring evidence (emails, numbers) so the list is not opinion. Watch for the client who fills the growth area with three paragraphs and the contributions with one line; rebalance in session.', '[{"id": "f0", "type": "textarea", "label": "Something I contributed in each quarter of this year, one line each:"}, {"id": "f1", "type": "textarea", "label": "A problem I solved this year that nobody asked me to:"}, {"id": "f2", "type": "textarea", "label": "A colleague who would speak well of my work, and what they would say:"}, {"id": "f3", "type": "textarea", "label": "One area I want to grow in next year, written as a plan, not an apology:"}, {"id": "f4", "type": "textarea", "label": "What I want to ask for in the review (title, pay, scope, support):"}, {"id": "f5", "type": "textarea", "label": "What I will do in the first ten minutes if the review goes badly:"}]'::jsonb, array['work', 'planning', 'assertiveness']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('roommate-shared-groceries-who-ate-what-talk-sheet', 'Roommate Shared Groceries Who Ate What Talk Sheet', 'worksheet'::resource_kind, 'A conversation prep sheet for a client whose shared kitchen has become a quiet war over missing food.', 'Use it to turn a resentment that has built for weeks into one direct, fair conversation with a roommate.', array['Adults']::text[], '20 minutes', 'Shared food is a small matter that stands in for a bigger one: whether the client can ask for anything. The sheet asks what specifically has gone missing, what the client has done instead of asking (labels, passive notes, buying less), what fair would look like to them, and a two-sentence opener for the conversation. Rehearse the opener aloud in session. Watch for the client who has already decided the roommate is a thief; slow that down and get them curious about what the roommate thinks the arrangement is.', '[{"id": "f0", "type": "textarea", "label": "What has actually gone missing or been used, as specifically as I can say it:"}, {"id": "f1", "type": "textarea", "label": "What I have done instead of asking (notes, labels, going quiet, buying less):"}, {"id": "f2", "type": "textarea", "label": "What a fair arrangement would look like to me:"}, {"id": "f3", "type": "textarea", "label": "The two sentences I will open the conversation with:"}, {"id": "f4", "type": "textarea", "label": "What I think my roommate believes our arrangement is, and how I would find out:"}, {"id": "f5", "type": "textarea", "label": "What I will do if the answer is unfair or dismissive:"}]'::jsonb, array['communication', 'assertiveness', 'household']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('expired-car-inspection-sticker-avoidance-steps-sheet', 'Expired Car Inspection Sticker Avoidance Steps Sheet', 'worksheet'::resource_kind, 'A steps sheet for a client who has driven past the expired inspection date for months and dreads dealing with it.', 'Use it to break an avoided errand into booked steps and name what the client has been dreading most.', array['Adults']::text[], '15 minutes, then one week', 'An expired sticker is a small avoided task with a growing cost: a ticket, a fail, a repair bill the client imagines before they have been seen. The sheet names what they fear the inspection will find, the actual first step (find a station, book a slot), the money set aside, and the day and time it will happen. The dread usually shrinks once the fear is written down and compared with what a fail actually costs. Watch for the client who avoids every errand with a possible bad result; this sheet is a template for the pattern, not just the sticker.', '[{"id": "f0", "type": "textarea", "label": "How long the sticker has been expired, and what has happened so far:"}, {"id": "f1", "type": "textarea", "label": "What I am afraid the inspection will find or cost:"}, {"id": "f2", "type": "textarea", "label": "The first step (find a station, book a slot) and when I will do it:"}, {"id": "f3", "type": "textarea", "label": "The day and time of the appointment, and what I have set aside for it:"}, {"id": "f4", "type": "textarea", "label": "If it fails, what I will do first:"}, {"id": "f5", "type": "textarea", "label": "Other errands I avoid this same way:"}]'::jsonb, array['avoidance', 'planning', 'problem solving']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('everyone-else-is-having-a-better-holiday-comparison-sheet', 'Everyone Else Is Having a Better Holiday Comparison Sheet', 'cbt'::resource_kind, 'A CBT sheet for the client whose feed of other people''s holidays convinces them theirs is a failure.', 'Use it to catch the comparison, examine what is actually being compared and widen the client''s view of their own day.', array['Adults', 'Teens']::text[], '20 minutes', 'Holiday photos are a highlight reel, and the client who scrolls them at the kitchen table compares their whole day with a stranger''s best thirty seconds. The sheet asks for the comparison thought, what evidence it rests on (a photo, a caption), what is left out of that evidence, and what the client''s own day would look like edited the same way. End by asking what they would want their day to be, independent of anyone else''s. Watch for the client who turns this into a reason to post more; the goal is less comparison, not better content.', '[{"id": "f0", "type": "textarea", "label": "The comparison thought that showed up, word for word:"}, {"id": "f1", "type": "textarea", "label": "What I was looking at when it showed up, and how long I had been scrolling:"}, {"id": "f2", "type": "textarea", "label": "What that photo or post leaves out that I cannot see:"}, {"id": "f3", "type": "textarea", "label": "What my own day would look like as a highlight reel:"}, {"id": "f4", "type": "textarea", "label": "What I would want from this holiday if nobody else''s existed:"}, {"id": "f5", "type": "textarea", "label": "One thing I will do differently with my phone over the holiday:"}]'::jsonb, array['comparison', 'thinking traps', 'core CBT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('burned-rolls-means-i-ruined-dinner-overgeneralization-sheet', 'Burned Rolls Means I Ruined Dinner Overgeneralization Sheet', 'cbt'::resource_kind, 'A CBT sheet for the client who turns one kitchen mistake into proof the whole meal, and the whole day, is ruined.', 'Use it to name overgeneralization in the moment and shrink a single mishap back to its real size.', array['Adults']::text[], '15 minutes', 'One burned tray can trigger a cascade for the client who runs on all-or-nothing rules about hosting: the rolls are ruined, so dinner is ruined, so I ruin things. The sheet asks for the mishap, the generalization that followed, how far it spread (the dish, the meal, the day, the self), what else was true about the meal, and what a guest actually noticed. It works best filled out after a real event while the feeling is fresh but the evidence is available. Watch for the client who agrees the rolls were fine but keeps the self-judgment intact; that layer is the one to work on.', '[{"id": "f0", "type": "textarea", "label": "The mistake, in plain words:"}, {"id": "f1", "type": "textarea", "label": "The thought that followed, and how far it spread (the dish, the meal, the day, me):"}, {"id": "f2", "type": "textarea", "label": "What else was true about the meal that the thought skipped:"}, {"id": "f3", "type": "textarea", "label": "What a guest actually said or noticed about it:"}, {"id": "f4", "type": "textarea", "label": "The same mistake described as a friend would describe it:"}, {"id": "f5", "type": "textarea", "label": "What I will say to myself the next time something burns:"}]'::jsonb, array['overgeneralization', 'thinking traps', 'core CBT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('parking-lot-scrape-hot-thought-record', 'Parking Lot Scrape Hot Thought Record', 'cbt'::resource_kind, 'A thought record for the client who scraped a car in a crowded lot and has been replaying it as a verdict on themselves.', 'Use it to catch the hot thought behind a minor accident and test it against the facts of a crowded parking lot.', array['Adults', 'Teens']::text[], '20 minutes', 'A scrape in a packed holiday lot is a small, common event that lands hard on a client with a harsh inner judge: careless, stupid, always. The record takes the situation, the hot thought, the emotion and its strength, the evidence for and against, and a balanced thought. Press for the evidence against: how tight the spaces were, how many cars had similar marks, what they did afterward (left a note, told the owner). Watch for the thought record that is all evidence for; the client may need you to supply the first item against.', '[{"id": "f0", "type": "textarea", "label": "What happened, in one or two factual sentences:"}, {"id": "f1", "type": "textarea", "label": "The hot thought about myself that showed up:"}, {"id": "f2", "type": "textarea", "label": "The feeling and how strong it was, 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "Evidence that supports the hot thought:"}, {"id": "f4", "type": "textarea", "label": "Evidence against it (the lot, the spaces, what I did afterward):"}, {"id": "f5", "type": "textarea", "label": "A more balanced thought, and how strong the feeling is now:"}]'::jsonb, array['thought record', 'automatic thoughts', 'core CBT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('checkout-line-compliment-discounting-the-positive-sheet', 'Checkout Line Compliment Discounting the Positive Sheet', 'cbt'::resource_kind, 'A CBT sheet for the client who brushes off a stranger''s kind word in seconds and keeps a critic''s remark for years.', 'Use it to catch the discounting as it happens and let one small positive stand on the record.', array['Adults', 'Teens']::text[], 'Ten minutes daily for one week', 'Discounting the positive is quick and quiet: a cashier says nice coat, the client thinks she says that to everyone, and the moment is gone. The sheet logs one positive each day (a compliment, a thank you, something going right), the discount that followed, and what it would mean to take it at face value. Ask for the exact words of the discount; they tend to repeat. Watch for the client who cannot find one positive in a day; that is useful information in itself, and the log can start with what they would count if they let themselves.', '[{"id": "f0", "type": "textarea", "label": "The positive thing that happened today, as exactly as I can remember it:"}, {"id": "f1", "type": "textarea", "label": "How I discounted it, in the words I used in my head:"}, {"id": "f2", "type": "textarea", "label": "What it would mean about me if I took it at face value:"}, {"id": "f3", "type": "textarea", "label": "A negative comment I have kept for years, and why that one counts and this one does not:"}, {"id": "f4", "type": "textarea", "label": "One way I could let today''s positive stand (write it down, say thank you, tell someone):"}]'::jsonb, array['discounting the positive', 'thinking traps', 'core CBT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('should-have-called-my-aunt-should-statements-sheet', 'Should Have Called My Aunt Should Statements Sheet', 'cbt'::resource_kind, 'A CBT sheet for the client carrying a list of family contacts they should have made and the guilt that comes with each one.', 'Use it to turn a pile of holiday shoulds into a few chosen wants and a plan the client can actually follow.', array['Adults']::text[], '20 minutes', 'The holidays multiply shoulds: should have called, should have visited, should have sent a card. The sheet lists the shoulds, asks who set each rule and when, what the client actually wants in each relationship, and which two they will act on this week. Changing should to want or choose is the move; a should that survives that test is a real value, and the rest are inherited rules. Watch for the client who converts every should into a want and then has a longer to-do list; the goal is fewer, chosen contacts.', '[{"id": "f0", "type": "textarea", "label": "The shoulds I am carrying about family contact right now:"}, {"id": "f1", "type": "textarea", "label": "For each, who set the rule and how long I have followed it:"}, {"id": "f2", "type": "textarea", "label": "What I actually want in each of these relationships:"}, {"id": "f3", "type": "textarea", "label": "The two contacts I will choose to make this week, and how:"}, {"id": "f4", "type": "textarea", "label": "The ones I am setting down for now, and what I will tell myself about them:"}]'::jsonb, array['should statements', 'guilt', 'core CBT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('thoughts-as-parade-floats-passing-the-curb-page', 'Thoughts as Parade Floats Passing the Curb Page', 'act'::resource_kind, 'An ACT defusion page in which the client watches thoughts roll past like floats at a holiday parade.', 'Use it to give a client a seasonal image for letting thoughts pass without climbing aboard any of them.', array['Adults', 'Teens']::text[], 'Ten minutes daily for one week', 'The parade float image works for clients who find leaves on a stream too quiet: a float is loud, decorated and impossible to miss, and it still passes. The client stands at the curb and lets each thought roll by with its banner, noticing the ones they are tempted to run alongside. The notes should capture which floats came back around and what it was like to stay on the curb. Watch for the client who tries to stop the parade; the practice is watching, not emptying the street.', '[{"id": "f0", "type": "textarea", "label": "The floats that passed today, each one''s banner in a few words:"}, {"id": "f1", "type": "textarea", "label": "The float I most wanted to climb onto, and what happened when I stayed on the curb:"}, {"id": "f2", "type": "textarea", "label": "The float that came around more than once:"}, {"id": "f3", "type": "textarea", "label": "What I noticed in my body as the loud ones passed:"}, {"id": "f4", "type": "textarea", "label": "One moment this week I could stand at the curb for a minute:"}]'::jsonb, array['defusion', 'metaphor', 'core ACT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('values-at-the-crowded-family-table-page', 'Values at the Crowded Family Table Page', 'act'::resource_kind, 'An ACT values page for the client bracing for a long family meal and the versions of themselves that show up there.', 'Use it to choose who the client wants to be at the table before the first comment lands.', array['Adults']::text[], '20 minutes before the gathering', 'Family tables pull old roles out of people: the peacemaker, the quiet one, the one who leaves early. The page asks which role the client expects to fall into, what they value about family and about themselves, what acting on those values would look like across the meal, and what they are willing to feel to do it. Keep it about their own behavior, not about changing relatives. Watch for the client whose plan depends on everyone else behaving; bring it back to what is in their hands.', '[{"id": "f0", "type": "textarea", "label": "The role I usually fall into at this table:"}, {"id": "f1", "type": "textarea", "label": "What I value about family, in my own words:"}, {"id": "f2", "type": "textarea", "label": "What I value about who I am when I am at my best:"}, {"id": "f3", "type": "textarea", "label": "What acting on those values would look like at this meal, in two or three specific moments:"}, {"id": "f4", "type": "textarea", "label": "What I am willing to feel (awkward, annoyed, lonely) in order to do that:"}, {"id": "f5", "type": "textarea", "label": "One small thing I will do at the table that fits who I want to be:"}]'::jsonb, array['values', 'family', 'committed action']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('willing-to-say-i-do-not-know-at-the-table-page', 'Willing to Say I Do Not Know at the Table Page', 'act'::resource_kind, 'An ACT willingness page for the client who bluffs through conversations rather than admit they do not know something.', 'Use it to practice saying I do not know on purpose and notice what actually follows.', array['Adults', 'Teens']::text[], 'One week', 'Bluffing is a way of not feeling small, and it costs the client real conversation. The page asks where they bluff, what they fear would follow from I do not know, and plans three moments to say it plainly in low-stakes settings, noting what happened. The practice is tolerating the small drop in the stomach, not learning facts. Watch for the client who picks only moments where nobody could expect them to know; push for one where they usually fake it.', '[{"id": "f0", "type": "textarea", "label": "Where I usually bluff or nod along rather than say I do not know:"}, {"id": "f1", "type": "textarea", "label": "What I am afraid would happen if I said it plainly:"}, {"id": "f2", "type": "textarea", "label": "Three moments this week where I will say I do not know on purpose:"}, {"id": "f3", "type": "textarea", "label": "What actually happened each time, and what I felt in the first ten seconds:"}, {"id": "f4", "type": "textarea", "label": "What saying it made possible (a question, a real answer, a laugh):"}]'::jsonb, array['willingness', 'values', 'core ACT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('observer-self-scrolling-the-years-photos-page', 'Observer Self Scrolling the Year''s Photos Page', 'act'::resource_kind, 'An ACT self-as-context page in which the client looks back through a year of photos and notices who has been watching.', 'Use it to help a client feel the steady observer behind a year of changing moods, roles and bodies.', array['Adults', 'Teens']::text[], '30 minutes', 'The phone''s year-in-photos is a ready-made self-as-context exercise. The client scrolls slowly, pausing at a few images from different months, and notices what has changed (mood, hair, place, company) and what has stayed the same: the one noticing. The page asks for three photos, what was going on in each, and what the observer was doing. Pair it with a quiet breath before each photo. Watch for the client who drifts into judging the photos; return them to the noticing.', '[{"id": "f0", "type": "textarea", "label": "Three photos from different months, and what was going on for me in each:"}, {"id": "f1", "type": "textarea", "label": "What was different about me in each one (mood, place, people, body):"}, {"id": "f2", "type": "textarea", "label": "What was the same in all three: who was doing the looking?"}, {"id": "f3", "type": "textarea", "label": "What it is like to notice that part of me has been here the whole year:"}, {"id": "f4", "type": "textarea", "label": "One phrase I will use when I need to find that observer again:"}]'::jsonb, array['self-as-context', 'mindfulness', 'core ACT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('dishwater-hands-present-moment-page', 'Dishwater Hands Present Moment Page', 'act'::resource_kind, 'An ACT present-moment page that turns the pile of dishes after a gathering into ten minutes of contact with the senses.', 'Use it to give a client a daily chore in which to practice attention on warmth, weight and sound instead of rumination.', array['Adults', 'Teens']::text[], 'Ten minutes daily for one week', 'The sink is where many clients ruminate; the page makes it where they practice attention instead. Hands in warm water, the client notices temperature, the weight of a plate, the sound of water, the smell of soap, returning each time the mind leaves for the argument or the to-do list. The notes ask what pulled them away and how they came back. It is a practice, not a fix for a hard evening. Watch for the client who reports the mind never wandered; ask them to count the wanders next time and treat each return as the exercise.', '[{"id": "f0", "type": "textarea", "label": "What I noticed with my hands in the water (temperature, weight, texture):"}, {"id": "f1", "type": "textarea", "label": "What I heard and smelled while washing:"}, {"id": "f2", "type": "textarea", "label": "Where my mind went when it left, and how I noticed:"}, {"id": "f3", "type": "textarea", "label": "How I came back each time:"}, {"id": "f4", "type": "textarea", "label": "What was different about the end of the chore compared with usual:"}]'::jsonb, array['present moment', 'mindfulness', 'core ACT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('give-skills-with-the-relative-who-talks-politics-card', 'GIVE Skills With the Relative Who Talks Politics Card', 'dbt'::resource_kind, 'A DBT GIVE card for keeping a relationship intact across a holiday meal with a relative who brings up politics.', 'Use it to plan a gentle, interested, validating, easy-mannered stance that protects the relationship without debating.', array['Adults']::text[], '15 minutes before the gathering', 'GIVE (Gentle, act Interested, Validate, Easy manner) is for the moments when the relationship matters more than the point. The card asks the client to plan each element for a specific relative: a gentle tone they can keep, a question that shows interest in the person rather than the opinion, something true they can validate (the worry under the view), and an easy exit line. Rehearse the exit line in session. Watch for the client who confuses validating a feeling with agreeing with a claim; GIVE does neither of the latter.', '[{"id": "f0", "type": "textarea", "label": "The relative and the topic I expect to come up:"}, {"id": "f1", "type": "textarea", "label": "Gentle: how I will keep my tone and face when it does:"}, {"id": "f2", "type": "textarea", "label": "Interested: one question I can ask about them, not their opinion:"}, {"id": "f3", "type": "textarea", "label": "Validate: something true I can acknowledge about what they feel or worry about:"}, {"id": "f4", "type": "textarea", "label": "Easy manner: my light exit line when I have had enough:"}, {"id": "f5", "type": "textarea", "label": "What I want this relationship to look like in January:"}]'::jsonb, array['GIVE', 'interpersonal effectiveness', 'family']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('distract-with-accepts-through-the-airport-delay-card', 'Distract With ACCEPTS Through the Airport Delay Card', 'dbt'::resource_kind, 'A DBT ACCEPTS card for a client stuck at the gate with a delayed holiday flight and rising distress.', 'Use it to pre-pack a set of distractions for the hours at the gate so the delay does not become a crisis.', array['Adults', 'Teens']::text[], '15 minutes before the trip, then as needed', 'A gate delay with no information is a distress-tolerance moment that arrives on a schedule. ACCEPTS (Activities, Contributing, Comparisons, Emotions, Pushing away, Thoughts, Sensations) gives the client seven places to look. The card asks for one concrete option under each that fits a terminal: a downloaded show, helping a traveler with a stroller, a playlist that shifts mood, a crossword, a mint. Pack the options before the trip. Watch for the client who plans to use the delay to ruminate about missing the connection; that is the moment the card is for.', '[{"id": "f0", "type": "textarea", "label": "Activities: what I will have downloaded or in my bag:"}, {"id": "f1", "type": "textarea", "label": "Contributing: one small way I could help someone at the gate:"}, {"id": "f2", "type": "textarea", "label": "Emotions: a song, clip or photo that shifts how I feel:"}, {"id": "f3", "type": "textarea", "label": "Pushing away: how I will set the connection worry on a shelf until there is news:"}, {"id": "f4", "type": "textarea", "label": "Thoughts: a puzzle or count I can do in my seat:"}, {"id": "f5", "type": "textarea", "label": "Sensations: something to taste, hold or smell:"}, {"id": "f6", "type": "textarea", "label": "What I will do the moment the board actually updates:"}]'::jsonb, array['ACCEPTS', 'distress tolerance', 'travel']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('check-the-facts-on-the-unanswered-group-text-card', 'Check the Facts on the Unanswered Group Text Card', 'dbt'::resource_kind, 'A DBT check-the-facts card for the client who reads silence in a group chat as rejection.', 'Use it to separate what a quiet thread actually shows from the story the client''s emotion is telling.', array['Adults', 'Teens']::text[], 'Ten minutes', 'A message that gets no reply in a busy group thread is a reliable trigger for shame and anger. The card walks the client through the facts (what they sent, who has read it, how long it has been, what else is in the thread), the interpretation, the emotion and its intensity, and whether the emotion fits the facts. Have them fill it out on a real thread. Watch for the client who checks the facts, finds them neutral, and still plans to leave the chat; the urge to act is the next skill.', '[{"id": "f0", "type": "textarea", "label": "What I sent, and to which chat:"}, {"id": "f1", "type": "textarea", "label": "The facts: how long it has been, who has read it, what else is in the thread:"}, {"id": "f2", "type": "textarea", "label": "The story I am telling about why nobody replied:"}, {"id": "f3", "type": "textarea", "label": "The emotion and how strong it is, 0 to 100:"}, {"id": "f4", "type": "textarea", "label": "Does the emotion fit the facts, or the story? What would fit the facts?"}, {"id": "f5", "type": "textarea", "label": "What I will do with the urge to act on it:"}]'::jsonb, array['check the facts', 'core DBT', 'communication']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-the-smell-of-something-baking-card', 'Self-Soothe With the Smell of Something Baking Card', 'dbt'::resource_kind, 'A DBT self-soothe card built around the smell of bread, pie or cookies in the oven.', 'Use it to give a client one strong, reliable scent to settle the body on a hard afternoon at home.', array['Adults', 'Teens']::text[], '30 minutes, as needed', 'Smell is the fastest of the five senses to shift state, and an oven makes it available to almost anyone. The card asks what the client will bake or warm (store dough counts), where they will sit while it bakes, what they notice as the smell builds, and how their body is at the end compared with the start. It is a self-soothe skill, not a reward or a rule about eating; the point is the scent and the waiting. Watch for the client who turns it into a project; keep it to the simplest thing that smells good.', '[{"id": "f0", "type": "textarea", "label": "What I will put in the oven (store-bought is fine):"}, {"id": "f1", "type": "textarea", "label": "Where I will sit while it bakes, and what I will do with my hands:"}, {"id": "f2", "type": "textarea", "label": "What I notice as the smell builds, in the body and the breath:"}, {"id": "f3", "type": "textarea", "label": "How tense I was at the start and at the end, 0 to 10:"}, {"id": "f4", "type": "textarea", "label": "Another smell I could keep on hand for days without an oven:"}]'::jsonb, array['self-soothing', 'distress tolerance', 'core DBT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('stop-skill-before-texting-the-ex-over-the-holidays-card', 'STOP Skill Before Texting the Ex Over the Holidays Card', 'dbt'::resource_kind, 'A DBT STOP card for the lonely holiday evening when the urge to text an ex-partner arrives.', 'Use it to put a full stop between the urge and the send button, and plan what fills the pause.', array['Adults', 'Teens']::text[], 'Ten minutes, then as needed', 'Holiday evenings, old photos and a drink or two bring the ex back into the client''s thumb. STOP (Stop, Take a step back, Observe, Proceed mindfully) gives them four beats. The card plans each: the literal stop (phone face down), the step back (another room, a glass of water), what to observe (what they actually want: company, closure, to be chosen), and a mindful next step that fits their values. Write the text they would send and read it in session. Watch for the client who proceeds mindfully to the send button anyway; what matters is that it was a choice.', '[{"id": "f0", "type": "textarea", "label": "Stop: where the phone goes the moment I notice the urge:"}, {"id": "f1", "type": "textarea", "label": "Take a step back: the room I move to and what I do for two minutes:"}, {"id": "f2", "type": "textarea", "label": "Observe: what I actually want right now (company, closure, to be chosen, to hurt them):"}, {"id": "f3", "type": "textarea", "label": "The text I would have sent, written here instead:"}, {"id": "f4", "type": "textarea", "label": "Proceed mindfully: what I will do next that fits who I want to be:"}, {"id": "f5", "type": "textarea", "label": "Who else I could message tonight instead:"}]'::jsonb, array['STOP', 'core DBT', 'relationships']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('whose-family-gets-thanksgiving-this-year-pact-for-partners', 'Whose Family Gets Thanksgiving This Year Pact for Partners', 'couples'::resource_kind, 'A couples pact for deciding which family a couple spends the holiday with, and how the other family is handled.', 'Use it to move a yearly argument onto paper with a fair rotation both partners can defend to their relatives.', array['Couples']::text[], 'One session', 'The fight is rarely about the turkey; it is about whose family counts more and who has to deliver the bad news. Each partner writes their own hopes, what their family will say, and what they fear it means if their side loses. Then the couple drafts a rule for this year and next (alternate, split the day, host both) and decides who tells which family, in what words. Watch for the partner who agrees in session and then renegotiates alone with their mother; the pact includes telling the family together or with an agreed script.', '[{"id": "f0", "type": "textarea", "label": "Partner A: where I want to be this year, and what my family will say if we are not there:"}, {"id": "f1", "type": "textarea", "label": "Partner B: where I want to be this year, and what my family will say if we are not there:"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I am afraid it means if we go to the other side:"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I am afraid it means if we go to the other side:"}, {"id": "f4", "type": "textarea", "label": "Our rule for this year and next (alternate, split, host both, something else):"}, {"id": "f5", "type": "textarea", "label": "Who tells which family, in what words, and by when:"}, {"id": "f6", "type": "textarea", "label": "How we will back each other up if a relative pushes:"}]'::jsonb, array['couples', 'family', 'holidays']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('black-friday-shopping-together-or-apart-plan-for-partners', 'Black Friday Shopping Together or Apart Plan for Partners', 'couples'::resource_kind, 'A couples plan for the sale weekend when one partner loves the hunt and the other hates crowds and spending.', 'Use it to decide how the weekend goes, together or apart, with a budget both partners signed before the first deal.', array['Couples']::text[], '30 minutes', 'One partner sees a sport, the other sees a crowd and a credit card bill. Each writes what the weekend means to them and what they dread, then the couple agrees on a shared budget, which purchases need a check-in, and whether they go together, apart, or not at all. The dread column is where the conversation lives; the budget is where it ends. Watch for the partner who agrees to the budget and plans to hide the receipt; name that openly and plan what a surprise purchase will cost the relationship.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what the sale weekend means to me, and what I dread about it:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what the sale weekend means to me, and what I dread about it:"}, {"id": "f2", "type": "textarea", "label": "Our shared budget for the weekend, and what is already planned within it:"}, {"id": "f3", "type": "textarea", "label": "Purchases that need a check-in text before they happen:"}, {"id": "f4", "type": "textarea", "label": "Together, apart, or staying home: our plan for the day, hour by hour if needed:"}, {"id": "f5", "type": "textarea", "label": "How we will talk about it on Sunday night without a fight:"}]'::jsonb, array['couples', 'money', 'planning']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('overnight-guests-bathroom-and-morning-schedule-for-partners', 'Overnight Guests Bathroom and Morning Schedule for Partners', 'couples'::resource_kind, 'A couples sheet for the week relatives stay over, when one bathroom and one coffee pot have to serve six people.', 'Use it to split the hosting logistics in advance so the couple is not negotiating at 7 a.m. in the hallway.', array['Couples']::text[], '20 minutes before guests arrive', 'Houseguests expose a couple''s unspoken division of labor, usually at breakfast. Each partner writes what they expect of themselves during the visit and what they fear the other will leave to them, then the couple sets a morning order for the bathroom, who makes coffee and breakfast, who handles their own relatives'' requests, and a daily ten-minute check-in away from the guests. Watch for the partner whose family is visiting assuming the other will host; make the host role explicit and shared.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I expect to handle during the visit, and what I am afraid will land on me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I expect to handle during the visit, and what I am afraid will land on me:"}, {"id": "f2", "type": "textarea", "label": "Our bathroom order and rough times for the mornings:"}, {"id": "f3", "type": "textarea", "label": "Who makes coffee and breakfast, and who handles which relatives'' requests:"}, {"id": "f4", "type": "textarea", "label": "Where and when we will take ten minutes alone each day:"}, {"id": "f5", "type": "textarea", "label": "The signal one of us gives when they need a break from hosting:"}]'::jsonb, array['couples', 'household', 'fairness']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('hosting-cleanup-tonight-or-tomorrow-pact-for-partners', 'Hosting Cleanup Tonight or Tomorrow Pact for Partners', 'couples'::resource_kind, 'A couples pact for the end of a big dinner, when one partner must clean up before bed and the other wants to leave it.', 'Use it to settle the cleanup argument before the guests leave, with each partner''s reason understood.', array['Couples']::text[], '15 minutes', 'The cleanup fight is about more than dishes: one partner cannot rest with a messy kitchen, the other is depleted and reads the scrubbing as a rebuke. Each writes what a messy kitchen at midnight means to them and what they are too tired for, then the couple agrees on a minimum tonight (food away, one load running), a maximum, and who does what in the morning. Watch for the partner who does the whole thing alone at midnight and resents it; the pact needs a stopping point they will actually honor.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what a messy kitchen at midnight does to me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what a messy kitchen at midnight does to me:"}, {"id": "f2", "type": "textarea", "label": "The minimum we both agree to before bed:"}, {"id": "f3", "type": "textarea", "label": "The maximum anyone does tonight, and the stopping time:"}, {"id": "f4", "type": "textarea", "label": "Who does what in the morning, and by when:"}, {"id": "f5", "type": "textarea", "label": "What we will say to each other when the last guest leaves:"}]'::jsonb, array['couples', 'household', 'communication']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('who-answers-the-family-group-chat-pact-for-partners', 'Who Answers the Family Group Chat Pact for Partners', 'couples'::resource_kind, 'A couples pact for the holiday group chats that ping all day and leave one partner doing all the replying.', 'Use it to divide the family communication load and agree what gets answered, when, and by whom.', array['Couples']::text[], '20 minutes', 'Family group chats are a quiet labor the couple rarely discusses: one partner answers their own family and the other''s too, and nobody notices until they are exhausted. Each writes which chats they are in, how many they answer for the couple, and what it costs them. Then the couple divides the chats, sets reply hours, and decides what questions (arrival times, dietary needs, gifts) get a shared answer agreed first. Watch for the partner who wants to mute everything; silence has a family cost too, and the pact names who absorbs it.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the chats I am in, and which ones I answer for both of us:"}, {"id": "f1", "type": "textarea", "label": "Partner B: the chats I am in, and which ones I answer for both of us:"}, {"id": "f2", "type": "textarea", "label": "What answering all day costs each of us:"}, {"id": "f3", "type": "textarea", "label": "Who takes which chat from now on:"}, {"id": "f4", "type": "textarea", "label": "Our reply hours, and what waits until then:"}, {"id": "f5", "type": "textarea", "label": "Questions that get a shared answer before either of us replies:"}]'::jsonb, array['couples', 'communication', 'family']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('paper-plate-turkey-thank-you-feathers-craft', 'Paper Plate Turkey Thank You Feathers Craft', 'kids'::resource_kind, 'A craft in which a child builds a paper plate turkey whose feathers each name a person or thing they are thankful for.', 'Use it to give a child a hands-on way to notice good things and people without a lecture about gratitude.', array['Children']::text[], '30 minutes', 'A paper plate, a brown circle for the body and a fan of colored paper feathers make a turkey a young child can build in one sitting. On each feather they write or draw one thing they are glad about, with a prompt per feather (a person, a place, a food, something that happened, something about themselves). The parent builds their own turkey alongside and reads their feathers aloud first, so the child hears a grown-up name small, honest things. Watch for the child who only names objects; model a person and a moment.', '[{"id": "f0", "type": "textarea", "label": "A person I am glad is in my life (feather one):"}, {"id": "f1", "type": "textarea", "label": "A place I like being (feather two):"}, {"id": "f2", "type": "textarea", "label": "Something that happened this year that I liked (feather three):"}, {"id": "f3", "type": "textarea", "label": "Something about me I am glad about (feather four):"}, {"id": "f4", "type": "textarea", "label": "A feather my grown-up wrote, and what they said:"}, {"id": "f5", "type": "textarea", "label": "Where my turkey will live so I see it this week:"}]'::jsonb, array['children', 'gratitude', 'craft']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('hand-warmer-squeeze-calm-down-play', 'Hand Warmer Squeeze Calm Down Play', 'kids'::resource_kind, 'A calming play in which a child squeezes a warm hand warmer or rice sock and breathes until the warmth spreads.', 'Use it to give a child a cold-weather object to hold and squeeze that pairs warmth with slowing down.', array['Children']::text[], 'Ten minutes, as needed', 'A hand warmer, a microwaved rice sock, or a mug of warm water gives a child''s hands something to do while the breath slows. The child holds it, squeezes on the in-breath, softens on the out-breath, and tracks where the warmth travels (fingers, wrists, chest). The parent holds one too and breathes at the same pace so the child has a rhythm to borrow. Draw where the warmth went. Watch for the child who squeezes harder and faster when upset; slow your own hands and let them match you.', '[{"id": "f0", "type": "textarea", "label": "What I held, and how warm it was on a scale of snowball to soup:"}, {"id": "f1", "type": "textarea", "label": "Where the warmth went in my body (draw or write):"}, {"id": "f2", "type": "textarea", "label": "How many squeeze breaths it took to feel calmer:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up did next to me:"}, {"id": "f4", "type": "textarea", "label": "When I could use my warm squeeze this week:"}]'::jsonb, array['children', 'regulation', 'play']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('cardboard-box-cozy-hideout-feelings-den-build', 'Cardboard Box Cozy Hideout Feelings Den Build', 'kids'::resource_kind, 'A build in which a child turns a large box into a feelings den with a rule about what happens inside.', 'Use it to give a child a place they built themselves for big feelings, with the parent invited in on the child''s terms.', array['Children']::text[], '45 minutes to build, then as needed', 'A big box, blankets, a flashlight and markers make a den a child can retreat to without it being a time-out. The child decorates the outside, decides the rule for the inside (what feelings are allowed, what you do there, how you come out), and puts a sign on the door. The parent helps cut and tape, asks permission to enter, and practices knocking. The den is a place to settle, not a punishment, and the parent should never send the child there. Watch for the child who wants to live in the box; set hours together.', '[{"id": "f0", "type": "textarea", "label": "What my den looks like on the outside (draw or describe):"}, {"id": "f1", "type": "textarea", "label": "The rule for what happens inside my den:"}, {"id": "f2", "type": "textarea", "label": "Feelings that are allowed in my den:"}, {"id": "f3", "type": "textarea", "label": "How my grown-up asks to come in, and what I say:"}, {"id": "f4", "type": "textarea", "label": "How I know I am ready to come out:"}, {"id": "f5", "type": "textarea", "label": "What we put inside to make it cozy:"}]'::jsonb, array['children', 'self-soothing', 'craft']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('cranberry-string-patience-counting-craft', 'Cranberry String Patience Counting Craft', 'kids'::resource_kind, 'A craft in which a child threads cranberries onto string while counting breaths and noticing the urge to rush.', 'Use it to give a child a slow, repetitive task that practices patience with a parent working beside them.', array['Children']::text[], '20 minutes', 'Threading cranberries (or beads, or pasta) onto a long string is slow by design. The child threads one per slow breath, counting to a goal, and notices each time they want to hurry or quit. The parent threads their own string and names their own urge to rush out loud so the child learns the feeling has a name and passes. Hang the garland where the child can see it. Watch for the child who melts down when a berry splits; practice the restart as part of the game.', '[{"id": "f0", "type": "textarea", "label": "How many cranberries I threaded before I wanted to rush:"}, {"id": "f1", "type": "textarea", "label": "What rushing feels like in my body:"}, {"id": "f2", "type": "textarea", "label": "What I did when a berry split or fell off:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up said when they wanted to hurry:"}, {"id": "f4", "type": "textarea", "label": "Where our garland is hanging:"}]'::jsonb, array['children', 'patience', 'craft']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('paper-cup-telephone-feelings-call-play', 'Paper Cup Telephone Feelings Call Play', 'kids'::resource_kind, 'A play in which a child and parent talk through a string telephone made of two paper cups about something hard to say.', 'Use it to give a child distance and a prop for saying a feeling they will not say face to face.', array['Children']::text[], '20 minutes', 'Two paper cups and a length of string make a telephone that only works if both people hold it tight, which is the point. The child calls the parent from across the room and says one thing they are feeling; the parent listens, repeats it back through the cup, and asks one question. Then they swap. The distance and the game let a child say what they cannot say at the table. Watch for the parent who answers with advice; coach them to repeat and ask first.', '[{"id": "f0", "type": "textarea", "label": "Something I said into my cup today:"}, {"id": "f1", "type": "textarea", "label": "What my grown-up said back to me:"}, {"id": "f2", "type": "textarea", "label": "A feeling that is easier to say on the phone than at the table:"}, {"id": "f3", "type": "textarea", "label": "A question my grown-up asked me, and my answer:"}, {"id": "f4", "type": "textarea", "label": "What my grown-up told me through their cup:"}]'::jsonb, array['children', 'communication', 'play']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('gratitude-alphabet-race-game', 'Gratitude Alphabet Race Game', 'game'::resource_kind, 'A group game in which teams race through the alphabet naming something they are thankful for at each letter.', 'Use it to warm up a group, loosen perfectionism and get past the obvious answers by the time the alphabet runs out.', array['Groups', 'Teens']::text[], '15 minutes', 'Rules: split into two teams. On go, each team works through the alphabet aloud, one thing they are glad about per letter, no skipping (X and Q will be creative). A facilitator listens for any team that stalls; the first team to Z wins. Second round: each letter must be a person or a moment, not an object. Debrief: which letters were hard, what the second round changed, and which answer surprised the team. Watch for the member who contributes nothing; make round two go in turns.', '[{"id": "f0", "type": "textarea", "label": "The letters my team got stuck on:"}, {"id": "f1", "type": "textarea", "label": "An answer from the other team I liked:"}, {"id": "f2", "type": "textarea", "label": "What changed when it had to be a person or a moment:"}, {"id": "f3", "type": "textarea", "label": "One thing I said that surprised me:"}, {"id": "f4", "type": "textarea", "label": "A letter I would answer differently tomorrow:"}]'::jsonb, array['group', 'game', 'gratitude']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('count-to-twenty-without-overlap-group-game', 'Count to Twenty Without Overlap Group Game', 'game'::resource_kind, 'A circle game in which the group counts to twenty with eyes closed, one voice at a time, restarting whenever two overlap.', 'Use it to practice patience, tolerating silence and letting go of control in a group that talks over itself.', array['Groups', 'Teens']::text[], '15 minutes', 'Rules: the group sits in a circle, eyes closed. Anyone may say the next number, but if two people speak at once the count returns to one. No order, no gestures, no leader. The group will fail many times before reaching twenty, and the silences get longer and more uncomfortable. Debrief: who jumped in early, who never spoke, what the silence felt like in the body, and what finally worked. Watch for the member who tries to run the count with a system; ask what it is like to let that go.', '[{"id": "f0", "type": "textarea", "label": "How many tries it took us to reach twenty, or how far we got:"}, {"id": "f1", "type": "textarea", "label": "What the silence before a number felt like in my body:"}, {"id": "f2", "type": "textarea", "label": "Was I a jumper-in or a waiter? What that is like for me elsewhere:"}, {"id": "f3", "type": "textarea", "label": "What finally worked for the group:"}, {"id": "f4", "type": "textarea", "label": "Where in my week I could use the pause before speaking:"}]'::jsonb, array['group', 'game', 'regulation']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('sound-ball-imaginary-toss-game', 'Sound Ball Imaginary Toss Game', 'game'::resource_kind, 'A circle game in which the group throws an invisible ball, each throw with a sound the catcher must echo before throwing on.', 'Use it to get a self-conscious group making noise, making eye contact and recovering from silly mistakes.', array['Groups', 'Teens', 'Children']::text[], 'Ten minutes', 'Rules: stand in a circle. The thrower makes eye contact, mimes a toss and makes a sound (whoosh, boing, a word). The catcher catches it with the same sound, then throws a new one with a new sound. Speed up; add a second ball. Debrief: what it was like to make a sound in front of everyone, who dropped the eye contact, and what the group did when a catch was missed. It is a warm-up for groups where members avoid eye contact or hate being watched. Watch for the member who only ever throws back to the same safe person.', '[{"id": "f0", "type": "textarea", "label": "The sound I threw most, and the sound I liked catching:"}, {"id": "f1", "type": "textarea", "label": "How it felt to make a noise in front of the group the first time, and the fifth:"}, {"id": "f2", "type": "textarea", "label": "Who I threw to, and who I avoided throwing to:"}, {"id": "f3", "type": "textarea", "label": "What the group did when someone missed a catch:"}, {"id": "f4", "type": "textarea", "label": "One thing from this game I want to remember about being watched:"}]'::jsonb, array['group', 'game', 'social skills']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('one-word-at-a-time-circle-story-game', 'One Word at a Time Circle Story Game', 'game'::resource_kind, 'A circle game in which the group builds a story one word per person, with no planning and no backing up.', 'Use it to practice letting go of a plan, accepting what the last person offered and staying present.', array['Groups', 'Teens', 'Children']::text[], '15 minutes', 'Rules: around the circle, each person adds exactly one word to a story. No pausing longer than three seconds, no changing another person''s word, and the story can go anywhere. A facilitator says ''the end'' after two or three rounds. Then play again with a theme (a hard day, a brave moment). Debrief: who tried to steer the story, what it was like when it went somewhere you did not want, and what the group did with the weird words. Watch for the member who freezes at their turn; let them pass once, then come back.', '[{"id": "f0", "type": "textarea", "label": "A sentence from our story I remember:"}, {"id": "f1", "type": "textarea", "label": "What I wanted the story to do, and what it did instead:"}, {"id": "f2", "type": "textarea", "label": "What it was like to have three seconds and one word:"}, {"id": "f3", "type": "textarea", "label": "What the group did with a word that did not fit:"}, {"id": "f4", "type": "textarea", "label": "Where in my life I try to steer a story that has other authors:"}]'::jsonb, array['group', 'game', 'communication']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('back-to-back-stand-up-partner-game', 'Back to Back Stand Up Partner Game', 'game'::resource_kind, 'A partner game in which two people sit back to back, link arms and try to stand up together without using their hands.', 'Use it to give a group a physical experience of cooperation, timing and asking for what you need from a partner.', array['Groups', 'Teens']::text[], '15 minutes', 'Rules: pairs sit on the floor back to back with arms linked, then try to stand up together by pushing against each other, no hands on the floor. Swap partners after each success or three failures; then try groups of three and four. Keep it safe: no one with a back or knee problem plays, and the floor is clear. Debrief: who talked and who just pushed, what it took to get the timing right, and what asking a partner to go slower was like. Watch for the pair that gives up silently; ask what each thought the other wanted.', '[{"id": "f0", "type": "textarea", "label": "How many tries it took with my first partner, and what changed the time it worked:"}, {"id": "f1", "type": "textarea", "label": "What I said to my partner, and what I wished I had said:"}, {"id": "f2", "type": "textarea", "label": "What it was like to depend on someone else''s push:"}, {"id": "f3", "type": "textarea", "label": "What the group of four needed that the pair did not:"}, {"id": "f4", "type": "textarea", "label": "Someone in my life I am trying to stand up with, and what this showed me:"}]'::jsonb, array['group', 'game', 'connection']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('crowded-parade-exit-route-plan-sheet', 'Crowded Parade Exit Route Plan Sheet', 'worksheet'::resource_kind, 'A planning sheet for a client who wants to attend a crowded holiday parade and needs exits, anchors and a leave-early rule.', 'Use it to make a crowded public event approachable with a plan for where to stand, how to leave and who to lean on.', array['Adults', 'Teens']::text[], '20 minutes before the event', 'Crowds, noise and no clear exit are a hard combination for a client whose nervous system still expects danger. The sheet plans the spot (an edge, near a side street), two exit routes walked in advance, a companion who knows the plan, a grounding anchor to carry, and an agreed point at which leaving is a success rather than a failure. The goal is attending on their own terms, not enduring the whole thing. Watch for the client who plans to stay in the thick of it to prove a point; staying is not the measure.', '[{"id": "f0", "type": "textarea", "label": "Where I will stand, and why that spot:"}, {"id": "f1", "type": "textarea", "label": "My two exit routes, walked or mapped beforehand:"}, {"id": "f2", "type": "textarea", "label": "Who is coming with me, and what they know about my plan:"}, {"id": "f3", "type": "textarea", "label": "The grounding anchor I will carry (an object, a smell, a phrase):"}, {"id": "f4", "type": "textarea", "label": "The point at which leaving counts as a success:"}, {"id": "f5", "type": "textarea", "label": "What I will do in the first ten minutes after I get home:"}]'::jsonb, array['PTSD and trauma', 'safety', 'planning']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('relaxing-means-letting-my-guard-down-belief-check-sheet', 'Relaxing Means Letting My Guard Down Belief Check Sheet', 'cbt'::resource_kind, 'A CBT sheet for the client who cannot rest because any ease feels like dropping their defenses.', 'Use it to examine the belief that relaxing is unsafe and test small, chosen moments of ease against it.', array['Adults', 'Teens']::text[], '20 minutes, then one week', 'For a client whose vigilance once kept them safe, relaxing can feel like negligence. The sheet names the belief in their words, where it came from, what it has cost (sleep, holidays, closeness), and what evidence there is that ease in a safe place has led to harm recently. Then it plans three short, chosen moments of rest in a place they rate as safe, with a note on what happened. Keep the moments small; the belief does not need to be argued away, only tested. Watch for the client who rates nowhere as safe; start there, not with the experiments.', '[{"id": "f0", "type": "textarea", "label": "The belief in my own words (relaxing means...):"}, {"id": "f1", "type": "textarea", "label": "Where this belief came from, and when it was useful:"}, {"id": "f2", "type": "textarea", "label": "What it costs me now (sleep, holidays, closeness, health):"}, {"id": "f3", "type": "textarea", "label": "Evidence that resting in a safe place has led to harm in the last year:"}, {"id": "f4", "type": "textarea", "label": "Three short moments of rest I will try this week, and where:"}, {"id": "f5", "type": "textarea", "label": "What actually happened each time:"}]'::jsonb, array['PTSD and trauma', 'core beliefs', 'safety']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('flashback-as-a-rerun-not-a-live-broadcast-page', 'Flashback as a Rerun Not a Live Broadcast Page', 'act'::resource_kind, 'An ACT page that frames an intrusive memory as a rerun of an old program, not live footage of something happening now.', 'Use it to give a client language for noticing that a memory is a replay, and anchors for coming back to the present channel.', array['Adults', 'Teens']::text[], '15 minutes, then as needed', 'The rerun image helps a client hold a memory as a memory: it is old footage, it has played before, and the room they are in is the live channel. The page asks them to describe their present room in detail (the live channel), name the rerun without describing its content, and list what tells them which one they are watching (the date, their age, the floor under their feet). This is an in-session grounding tool first; practice it on a quiet day before using it on a hard one. Watch for the client who tries to change the channel by force; the move is noticing which channel is on.', '[{"id": "f0", "type": "textarea", "label": "The live channel: five things I can see and touch in the room I am in right now:"}, {"id": "f1", "type": "textarea", "label": "The rerun: what I call it, in a few words, without describing what happens in it:"}, {"id": "f2", "type": "textarea", "label": "What tells me a rerun has started (body signals, sounds, a feeling of now being then):"}, {"id": "f3", "type": "textarea", "label": "What tells me I am on the live channel (the date, my age, who is here):"}, {"id": "f4", "type": "textarea", "label": "The phrase I will use when I notice the rerun:"}, {"id": "f5", "type": "textarea", "label": "Who I can tell afterward that a rerun played:"}]'::jsonb, array['PTSD and trauma', 'metaphor', 'grounding']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('tipp-cold-air-sixty-seconds-on-the-step-card', 'TIPP Cold Air Sixty Seconds on the Step Card', 'dbt'::resource_kind, 'A DBT TIPP card using one minute of cold outdoor air to bring down a body that has spiked after a trigger.', 'Use it to give a client a fast, season-ready temperature skill they can reach from any doorway.', array['Adults', 'Teens']::text[], 'Five minutes, as needed', 'TIPP (Temperature, Intense exercise, Paced breathing, Paired muscle relaxation) starts with temperature, and in late fall the cold is right outside the door. The card plans sixty seconds on the step: face and hands in the cold air, slow out-breaths, counting, then back inside for paced breathing. The client logs what their body did before and after. It is a body skill, not a thinking skill; keep the instructions physical. Watch for the client who stays out until they are shivering; the point is a shift, not an ordeal, and sixty seconds is the rule.', '[{"id": "f0", "type": "textarea", "label": "Where my step or doorway is, and what I will stand on:"}, {"id": "f1", "type": "textarea", "label": "What my body was doing before (heart, breath, jaw, hands):"}, {"id": "f2", "type": "textarea", "label": "What I noticed during the sixty seconds of cold:"}, {"id": "f3", "type": "textarea", "label": "The paced breathing I will do once I am back inside:"}, {"id": "f4", "type": "textarea", "label": "What my body was doing five minutes later:"}, {"id": "f5", "type": "textarea", "label": "Another temperature option for when I cannot get outside:"}]'::jsonb, array['PTSD and trauma', 'TIPP', 'distress tolerance']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('where-i-sit-at-the-big-dinner-plan-for-partners', 'Where I Sit at the Big Dinner Plan for Partners', 'couples'::resource_kind, 'A couples plan for seating at a large gathering so the partner with a startle response has their back covered and an exit.', 'Use it to let both partners plan the seat, the exit and the signal before the meal, and agree what the other does.', array['Couples']::text[], '20 minutes before the gathering', 'For a partner who needs a wall behind them and a door in view, the seating at a big dinner is not trivial, and the other partner often does not know. Each writes what they need from the seating, then the couple decides the seat, who sits beside whom, the exit, the quiet signal for needing a break, and what the other partner does when it is given (follows, covers, stays). The point is both partners knowing the plan without it being announced to the table. Watch for the partner who feels controlled by the plan; make their needs the other half of the sheet.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I need from where we sit, and why:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need from where we sit, and what I want to understand better:"}, {"id": "f2", "type": "textarea", "label": "Our seats, and who is beside each of us:"}, {"id": "f3", "type": "textarea", "label": "The exit, and the quiet signal for needing a break:"}, {"id": "f4", "type": "textarea", "label": "What the other partner does when the signal is given:"}, {"id": "f5", "type": "textarea", "label": "What we will say to the host if we need to change seats:"}]'::jsonb, array['PTSD and trauma', 'couples', 'safety']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('refreshing-the-flight-status-page-checking-log-sheet', 'Refreshing the Flight Status Page Checking Log Sheet', 'worksheet'::resource_kind, 'A log sheet for the client who refreshes the airline app every few minutes before a holiday flight.', 'Use it to count the checking, link it to the anxiety it feeds and set a spacing plan the client agrees to.', array['Adults', 'Teens']::text[], 'One travel day', 'Refreshing the status page feels like doing something, and each refresh buys a few seconds of relief before the worry returns. The sheet logs each check, the anxiety before and after (0 to 10), what changed on the screen (usually nothing), and the worry that drove it. Then the client sets a spacing rule for the rest of the day and notes what they did in the gaps. Watch for the client who stops checking the app and starts checking the departures board instead; the behavior moves, and the log should follow it.', '[{"id": "f0", "type": "textarea", "label": "Each time I checked: the time, anxiety before and after, and what had changed:"}, {"id": "f1", "type": "textarea", "label": "The worry that sends me back to the app, in one sentence:"}, {"id": "f2", "type": "textarea", "label": "How many checks so far today, and how many actually gave me new information:"}, {"id": "f3", "type": "textarea", "label": "My spacing rule for the rest of the day (every 30 minutes, every hour, only on alerts):"}, {"id": "f4", "type": "textarea", "label": "What I will do in the gaps between checks:"}, {"id": "f5", "type": "textarea", "label": "What I notice about the worry after an hour of not checking:"}]'::jsonb, array['anxiety', 'checking', 'self-monitoring']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('if-the-turkey-is-dry-everyone-will-judge-probability-sheet', 'If the Turkey Is Dry Everyone Will Judge Probability Sheet', 'cbt'::resource_kind, 'A CBT probability sheet for the host whose anxiety about one dish has become a prediction about every guest''s opinion.', 'Use it to estimate the real odds of the feared outcome and of its feared consequences, link by link.', array['Adults']::text[], '20 minutes', 'Hosting anxiety stacks predictions: the dish will fail, people will notice, they will judge, they will say so, the day will be about it. The sheet writes out the chain, assigns each link a rough probability, multiplies them, and compares the result with how certain the client feels. Then it asks what guests have actually said about imperfect meals in the past and what the client thinks about a dry dish at someone else''s table. Watch for the client who gives every link ninety percent; test one link at a time against memory.', '[{"id": "f0", "type": "textarea", "label": "The feared chain, link by link (the dish fails, people notice, they judge, they say so, the day is ruined):"}, {"id": "f1", "type": "textarea", "label": "My rough odds for each link, and the odds of the whole chain happening:"}, {"id": "f2", "type": "textarea", "label": "How certain it feels, 0 to 100, compared with the number I just worked out:"}, {"id": "f3", "type": "textarea", "label": "What guests have actually said about imperfect dishes at past meals:"}, {"id": "f4", "type": "textarea", "label": "What I think when a dish at someone else''s table is not great:"}, {"id": "f5", "type": "textarea", "label": "What I will do if the dish really is dry:"}]'::jsonb, array['anxiety', 'probability', 'thinking traps']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('anxious-mind-as-a-car-alarm-set-off-by-the-wind-page', 'Anxious Mind as a Car Alarm Set Off by the Wind Page', 'act'::resource_kind, 'An ACT defusion page in which the client sees anxious alarms as a car alarm that goes off at the wind, not at thieves.', 'Use it to help a client thank the alarm, check the facts and step back from treating every alert as a real break-in.', array['Adults', 'Teens']::text[], 'Ten minutes, then one week', 'A car alarm that shrieks at wind and passing trucks is loud, useless and still doing its job as it understands it. The page invites the client to name their alarm, log what set it off this week (a gust or an actual thief), notice how long it blared, and practice a short acknowledgment (thanks, I will look) before returning to what they were doing. It is defusion, not reassurance: the alarm can stay on while the client gets on with the day. Watch for the client who wants to disable the alarm entirely; the aim is a lighter relationship with it.', '[{"id": "f0", "type": "textarea", "label": "What set my alarm off this week, and whether it was a gust or a real intruder:"}, {"id": "f1", "type": "textarea", "label": "How long the alarm blared each time, and what I did while it did:"}, {"id": "f2", "type": "textarea", "label": "My short acknowledgment phrase for the alarm:"}, {"id": "f3", "type": "textarea", "label": "What I went back to doing while it was still sounding:"}, {"id": "f4", "type": "textarea", "label": "What I notice about the alarm by the end of the week:"}]'::jsonb, array['anxiety', 'defusion', 'metaphor']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('cope-ahead-for-the-dinner-table-question-about-my-job-card', 'Cope Ahead for the Dinner Table Question About My Job Card', 'dbt'::resource_kind, 'A DBT cope-ahead card for the moment a relative asks what the client is doing for work and the honest answer is hard.', 'Use it to rehearse the answer, the feeling and the recovery before the question lands at the table.', array['Adults']::text[], '20 minutes before the gathering', 'The question comes every year, and the client who is between jobs or in a role they are not proud of dreads it for weeks. Cope ahead has them describe the moment in detail, choose the one-sentence answer they can say without flinching, imagine the feeling arriving, rehearse the skills they will use (a breath, a redirect question, an exit), and picture it going as well as it realistically can. Rehearse aloud in session; a sentence they have said ten times is easier to say once more. Watch for the client who rehearses a lie; an honest short answer holds up better.', '[{"id": "f0", "type": "textarea", "label": "The relative most likely to ask, and the exact words they will use:"}, {"id": "f1", "type": "textarea", "label": "My one-sentence answer, said the way I want to say it:"}, {"id": "f2", "type": "textarea", "label": "The feeling I expect to arrive, and where I will feel it:"}, {"id": "f3", "type": "textarea", "label": "The skills I will use in the moment (a breath, a question back, an exit):"}, {"id": "f4", "type": "textarea", "label": "How the moment goes when it goes as well as it realistically can:"}, {"id": "f5", "type": "textarea", "label": "What I will do for myself afterward, whatever happened:"}]'::jsonb, array['anxiety', 'cope ahead', 'core DBT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('worry-paper-snowball-bucket-toss-game', 'Worry Paper Snowball Bucket Toss Game', 'game'::resource_kind, 'A group game in which worries are written on paper, crumpled into snowballs and tossed at a bucket from increasing distances.', 'Use it to externalize worries, make them light enough to throw and talk about what it took to let one go.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'Rules: each person writes two or three worries, one per sheet, crumples them into snowballs. Round one, everyone tosses from close range; a basket is a point. Each round the line moves back a step. A missed snowball is picked up, read aloud by its owner if they choose, and thrown again. Debrief: which worry was easiest to throw and which they wanted to hold onto, what the group did when a worry was read aloud, and what the distance changed. Watch for the member who writes a joke worry; let it stand, then ask for a real one in round two.', '[{"id": "f0", "type": "textarea", "label": "The worries I wrote on my snowballs:"}, {"id": "f1", "type": "textarea", "label": "Which one was easiest to throw, and which I wanted to keep:"}, {"id": "f2", "type": "textarea", "label": "What I felt reading a worry aloud, or hearing someone else''s:"}, {"id": "f3", "type": "textarea", "label": "What the group did when a worry landed in the bucket:"}, {"id": "f4", "type": "textarea", "label": "One worry I am leaving in the bucket this week, and what I will do instead of holding it:"}]'::jsonb, array['anxiety', 'group', 'game']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('one-text-back-before-the-day-ends-micro-step-sheet', 'One Text Back Before the Day Ends Micro Step Sheet', 'worksheet'::resource_kind, 'A micro step sheet for the client whose low mood has left a pile of unanswered messages and a growing sense of being a bad friend.', 'Use it to make one reply a day the whole task, and track what the reply changes in mood and connection.', array['Adults', 'Teens']::text[], 'Five minutes daily for one week', 'Unanswered messages pile up in low mood, and each one becomes heavier the longer it waits. The sheet shrinks the task to one reply a day: which message, the shortest honest reply (a sentence is fine, so is ''sorry for the slow reply, thinking of you''), the time it will be sent, and what happened afterward. The reply is the win regardless of the response. Watch for the client who drafts a long apology and sends nothing; the sheet asks for the shortest version that is true.', '[{"id": "f0", "type": "textarea", "label": "The message I will answer today, and how long it has waited:"}, {"id": "f1", "type": "textarea", "label": "The shortest honest reply I can send:"}, {"id": "f2", "type": "textarea", "label": "The time I will send it:"}, {"id": "f3", "type": "textarea", "label": "What I felt right before pressing send, and right after:"}, {"id": "f4", "type": "textarea", "label": "What came back, if anything, and what I made of it:"}, {"id": "f5", "type": "textarea", "label": "The message for tomorrow:"}]'::jsonb, array['depression', 'behavioral activation', 'connection']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('holiday-cheer-means-i-am-failing-at-happiness-sheet', 'Holiday Cheer Means I Am Failing at Happiness Sheet', 'cbt'::resource_kind, 'A CBT sheet for the client whose low mood feels like a personal failure against a season that demands cheer.', 'Use it to catch the should about feeling festive and separate a hard mood from a verdict on the client.', array['Adults', 'Teens']::text[], '20 minutes', 'The season tells the client to be merry, and when they are not, the mood becomes evidence of failing at something everyone else manages. The sheet names the should, where it is coming from (ads, family, memory), the thought that follows about the self, and what else could explain a low mood in late November (less light, more demands, a loss, a long year). Then it asks what a decent season would look like without the cheer requirement. Watch for the client who decides the answer is to skip the season entirely; aim for a smaller, honest version instead.', '[{"id": "f0", "type": "textarea", "label": "The should I am hearing about how I ought to feel this season:"}, {"id": "f1", "type": "textarea", "label": "Where it is coming from (ads, family, memories, my own rule):"}, {"id": "f2", "type": "textarea", "label": "The thought about me that follows when I do not feel that way:"}, {"id": "f3", "type": "textarea", "label": "Other explanations for a low mood right now (light, demands, loss, a long year):"}, {"id": "f4", "type": "textarea", "label": "What a decent season would look like for me without the cheer requirement:"}, {"id": "f5", "type": "textarea", "label": "One small thing I will do this week that fits that version:"}]'::jsonb, array['depression', 'should statements', 'thinking traps']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('low-mood-as-a-dim-winter-afternoon-not-the-night-page', 'Low Mood as a Dim Winter Afternoon Not the Night Page', 'act'::resource_kind, 'An ACT acceptance page that frames a low stretch as the dim light of a winter afternoon: real, temporary and still daylight.', 'Use it to help a client hold a low mood without concluding that the day, or they, are finished.', array['Adults', 'Teens']::text[], '15 minutes, then one week', 'Late November afternoons go dim by four, and a client in a low stretch often reads the dimness as night. The page asks them to describe the mood as light rather than as a verdict, what they can still see and do in dim light, what they would want to do if they were waiting for the light to come back, and what tells them it is afternoon and not midnight (meals still happen, people still text, they still got up). The point is making room for the dimness rather than fighting it. Watch for the client who hears this as ''cheer up''; it is permission to be dim, not an instruction to brighten.', '[{"id": "f0", "type": "textarea", "label": "If my mood were a kind of light, what it is like right now:"}, {"id": "f1", "type": "textarea", "label": "What I can still see and do in this light:"}, {"id": "f2", "type": "textarea", "label": "What tells me it is a dim afternoon and not the middle of the night:"}, {"id": "f3", "type": "textarea", "label": "What I would do while waiting for more light, if waiting were allowed:"}, {"id": "f4", "type": "textarea", "label": "One thing I will do this week that fits a dim afternoon:"}]'::jsonb, array['depression', 'acceptance', 'metaphor']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('build-mastery-by-taking-out-the-recycling-card', 'Build Mastery by Taking Out the Recycling Card', 'dbt'::resource_kind, 'A DBT build-mastery card that makes one neglected household task the day''s accomplishment during a low stretch.', 'Use it to give a client a daily task small enough to finish and real enough to count.', array['Adults', 'Teens']::text[], 'Five minutes daily for one week', 'Build mastery in a low stretch means picking a task that is a little hard and finishing it. The overflowing recycling bin is ideal: visible, concrete, slightly unpleasant and done in five minutes. The card names the task, the time, the first physical action (stand up, pick up the bin), what the client felt before and after, and what they said to themselves afterward. One task a day; a bigger one is not the aim. Watch for the client who adds four more chores on day two and quits by day four; hold them to one.', '[{"id": "f0", "type": "textarea", "label": "Today''s task, and the time I will do it:"}, {"id": "f1", "type": "textarea", "label": "The very first physical action (stand up, pick up the bin):"}, {"id": "f2", "type": "textarea", "label": "How hard it felt before I started, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "How hard it actually was, 0 to 10, and what I felt when it was done:"}, {"id": "f4", "type": "textarea", "label": "What I said to myself afterward (write what I would say to a friend who did it):"}, {"id": "f5", "type": "textarea", "label": "Tomorrow''s one task:"}]'::jsonb, array['depression', 'build mastery', 'core DBT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('quiet-company-hour-plan-for-partners', 'Quiet Company Hour Plan for Partners', 'couples'::resource_kind, 'A couples plan for an hour of being in the same room, with no talking required, when one partner is in a low stretch.', 'Use it to let both partners agree what quiet company looks like so one is not alone and the other is not performing.', array['Couples']::text[], '20 minutes to plan, then one hour daily', 'When one partner is low, the other often faces a choice between hovering and leaving them alone. Quiet company is a third option: the same room, two activities, no requirement to talk. Each partner writes what they want from the hour and what they fear (being a burden, being ignored, having to fix it), then the couple picks the time, the room, what each will do, and the one sentence either can say to end it early. Watch for the well partner who fills the hour with gentle questions; the plan includes what they will do with their own hands.', '[{"id": "f0", "type": "textarea", "label": "Partner A (in the low stretch): what I want from the hour, and what I do not want:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I want from the hour, and what I am afraid of getting wrong:"}, {"id": "f2", "type": "textarea", "label": "The time and the room:"}, {"id": "f3", "type": "textarea", "label": "What each of us will be doing with our hands:"}, {"id": "f4", "type": "textarea", "label": "The sentence either of us can say to end the hour early without a fight:"}, {"id": "f5", "type": "textarea", "label": "How we will know after a week whether this is helping:"}]'::jsonb, array['depression', 'couples', 'support']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('holiday-dish-to-bring-shopping-and-timing-sheet', 'Holiday Dish to Bring Shopping and Timing Sheet', 'worksheet'::resource_kind, 'A planning sheet for the client who signed up to bring a dish and has not thought about it until the morning of.', 'Use it to work backward from the arrival time to the shopping list, the start time and the transport plan.', array['Adults', 'Teens']::text[], '15 minutes, three days before', 'The dish is a small project with a hard deadline and four hidden steps, which is exactly what trips up a client whose planning happens in the moment. The sheet works backward from arrival: when the dish must be done, how long it takes (doubled), when shopping happens, what container it travels in, and the backup (a store-bought version) if the morning goes wrong. Write the shopping list on the sheet, not in the head. Watch for the client who picks an ambitious new recipe; steer toward one they have made before.', '[{"id": "f0", "type": "textarea", "label": "What I said I would bring, and when we are supposed to arrive:"}, {"id": "f1", "type": "textarea", "label": "How long the recipe says it takes, and that number doubled:"}, {"id": "f2", "type": "textarea", "label": "The time I will start cooking, and the time I will shop:"}, {"id": "f3", "type": "textarea", "label": "The shopping list, every item:"}, {"id": "f4", "type": "textarea", "label": "The container it travels in, and where that container is right now:"}, {"id": "f5", "type": "textarea", "label": "My backup if the morning falls apart:"}]'::jsonb, array['ADHD', 'planning', 'executive function']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('late-again-means-i-do-not-care-about-people-labeling-sheet', 'Late Again Means I Do Not Care About People Labeling Sheet', 'cbt'::resource_kind, 'A CBT labeling sheet for the client whose lateness has become proof, to themselves, that they are selfish.', 'Use it to separate a time-management pattern from a character verdict and plan one concrete change.', array['Adults', 'Teens']::text[], '20 minutes', 'Chronic lateness draws a moral label fast: selfish, careless, does not value anyone. The sheet names the label, lists the evidence for it (late) and the evidence against (the apologies, the effort, the things they do show up for), then asks what else explains the lateness (time blindness, transitions, underestimating travel) and one mechanical change to try. Separating the pattern from the person makes the change easier, not the lateness acceptable. Watch for the client who swaps ''selfish'' for ''broken''; both are labels.', '[{"id": "f0", "type": "textarea", "label": "The label I give myself when I am late:"}, {"id": "f1", "type": "textarea", "label": "Evidence that supports it:"}, {"id": "f2", "type": "textarea", "label": "Evidence against it (what I do show up for, how I feel when I am late, what I do to make up):"}, {"id": "f3", "type": "textarea", "label": "Other explanations for my lateness that are about time, not character:"}, {"id": "f4", "type": "textarea", "label": "One mechanical change to try this week (an alarm to leave, not to get ready; clothes out; travel time looked up):"}, {"id": "f5", "type": "textarea", "label": "What I will say to the person I am late for instead of a long apology:"}]'::jsonb, array['ADHD', 'labeling', 'core beliefs']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('attention-as-a-puppy-on-a-long-leash-page', 'Attention as a Puppy on a Long Leash Page', 'act'::resource_kind, 'An ACT page that treats a wandering attention as a puppy on a leash: it will pull, and the client can gently bring it back.', 'Use it to replace self-scolding about distraction with a lighter, repeatable return to the task.', array['Adults', 'Teens']::text[], 'Ten minutes daily for one week', 'A client who scolds themselves for every lapse in attention adds shame to the distraction. The puppy image is kinder and more accurate: puppies pull toward every smell, and the work is noticing and gently guiding, not yelling. The page asks them to pick a ten-minute task, count the pulls, note what the puppy went after, and practice a two-word return (come on, back here). The count usually falls over a week, but the point is the gentleness. Watch for the client who tries to keep the puppy perfectly still; that is not what puppies do.', '[{"id": "f0", "type": "textarea", "label": "The ten-minute task I practiced with today:"}, {"id": "f1", "type": "textarea", "label": "How many times the puppy pulled, and what it went after:"}, {"id": "f2", "type": "textarea", "label": "My two-word return phrase:"}, {"id": "f3", "type": "textarea", "label": "What I said to myself after a pull, compared with what I used to say:"}, {"id": "f4", "type": "textarea", "label": "What the end of the ten minutes was like:"}]'::jsonb, array['ADHD', 'metaphor', 'attention']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('one-mindfully-through-the-dish-pile-card', 'One-Mindfully Through the Dish Pile Card', 'dbt'::resource_kind, 'A DBT one-mindfully card for a client who abandons the dishes halfway because three other tasks pulled them away.', 'Use it to practice doing one task to the end with full attention, and notice each pull toward the next thing.', array['Adults', 'Teens']::text[], '15 minutes daily for one week', 'One-mindfully is the DBT skill of doing one thing at a time with the whole mind, and a dish pile is a fair test. The card sets up the task (phone in another room, timer off), asks the client to note each pull toward something else without following it, and to finish the pile before anything else. Afterward they log how many pulls, which were strongest, and what finishing felt like. Watch for the client who turns it into a speed challenge; the skill is attention, not pace.', '[{"id": "f0", "type": "textarea", "label": "Where my phone was, and what else I removed before starting:"}, {"id": "f1", "type": "textarea", "label": "The pulls I noticed toward other tasks, and roughly how many:"}, {"id": "f2", "type": "textarea", "label": "The strongest pull, and what I did with it:"}, {"id": "f3", "type": "textarea", "label": "What it was like to reach the end of the pile without leaving:"}, {"id": "f4", "type": "textarea", "label": "Another daily task I could do one-mindfully this week:"}]'::jsonb, array['ADHD', 'one-mindfully', 'core DBT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('sock-matching-race-with-a-finish-line-tape-play', 'Sock Matching Race With a Finish Line Tape Play', 'kids'::resource_kind, 'A play in which a child matches a pile of socks against a timer and runs the finished basket across a tape finish line.', 'Use it to give a child who starts chores and drifts off a clear, physical finish they can see and cross.', array['Children']::text[], '15 minutes', 'Finishing is the hard part for many children with scattered attention; starting is easy and the middle disappears. The sock race gives the task a visible end: a pile, a basket, a strip of tape on the floor, and a parent with a stopwatch. The child matches, fills the basket, and runs it across the line; the parent cheers the crossing, not the speed. Play twice and let the child predict their time. Watch for the parent who corrects mismatched pairs mid-race; corrections wait until after the line.', '[{"id": "f0", "type": "textarea", "label": "How many pairs I matched before I crossed the line:"}, {"id": "f1", "type": "textarea", "label": "My guess for how long it would take, and how long it took:"}, {"id": "f2", "type": "textarea", "label": "What my brain wanted to do instead, partway through:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up did when I crossed the line:"}, {"id": "f4", "type": "textarea", "label": "Another chore we could put a finish line on:"}]'::jsonb, array['ADHD', 'children', 'task initiation']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('thanksgiving-table-drink-refusal-line-sheet', 'Thanksgiving Table Drink Refusal Line Sheet', 'worksheet'::resource_kind, 'A planning sheet for the client who is not drinking this year and will be offered a glass at the family table by people who do not know.', 'Use it to script short refusals, decide what to hold, and plan who at the table is an ally.', array['Adults']::text[], '20 minutes before the gathering', 'The first family holiday without alcohol is a run of small offers from people who mean well. The sheet asks who will offer, the two or three short lines the client can say without explaining, what they will have in their hand all evening, which relative knows and can run interference, and the exit plan if the urge climbs. Rehearse the lines aloud until they are boring. Watch for the client who plans to tell the whole table; a short line and a full glass of something else usually serves better.', '[{"id": "f0", "type": "textarea", "label": "Who is likely to offer me a drink, and how:"}, {"id": "f1", "type": "textarea", "label": "My two or three short refusal lines, said without explaining:"}, {"id": "f2", "type": "textarea", "label": "What will be in my hand all evening:"}, {"id": "f3", "type": "textarea", "label": "The person at the table who knows, and what I want them to do:"}, {"id": "f4", "type": "textarea", "label": "What I will do if the urge climbs past a 6 out of 10:"}, {"id": "f5", "type": "textarea", "label": "How I will get home, and when I plan to leave:"}]'::jsonb, array['addiction', 'substance use', 'planning']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('everyone-drinks-at-the-holidays-permission-thought-sheet', 'Everyone Drinks at the Holidays Permission Thought Sheet', 'cbt'::resource_kind, 'A CBT sheet for the permission-giving thoughts that arrive before a holiday: everyone does it, just this once, it is tradition.', 'Use it to catch the permission thought early and answer it with the client''s own reasons and plan.', array['Adults']::text[], '20 minutes', 'Permission thoughts are the quiet negotiators of substance use, and the holidays give them their best material. The sheet lists the thoughts in the client''s words, what each one leaves out (what happened last time, what the client decided and why), a reply to each written in advance, and the person they will tell when one shows up. The reply must be the client''s, not yours; borrowed reasons collapse under a toast. Watch for the client who has no reply for ''it is tradition''; that one usually needs a new tradition, not an argument.', '[{"id": "f0", "type": "textarea", "label": "The permission thoughts I expect this holiday, in my own words:"}, {"id": "f1", "type": "textarea", "label": "What each one leaves out:"}, {"id": "f2", "type": "textarea", "label": "My reply to each, written as I would say it to myself:"}, {"id": "f3", "type": "textarea", "label": "The person I will tell when a permission thought shows up:"}, {"id": "f4", "type": "textarea", "label": "The new thing I am doing this holiday that could become a tradition:"}]'::jsonb, array['addiction', 'substance use', 'thinking traps']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('urge-as-a-doorbell-i-do-not-have-to-answer-page', 'Urge as a Doorbell I Do Not Have to Answer Page', 'act'::resource_kind, 'An ACT page that frames an urge as a doorbell: loud, insistent, and not an order to open the door.', 'Use it to give a client a way to hear the urge, let it ring and stay seated until it stops.', array['Adults', 'Teens']::text[], 'Ten minutes, then as needed', 'A doorbell demands a response in the body before the mind decides anything, which is what an urge does. The page has the client describe their doorbell (how loud, how long, what it sounds like), what they usually do when it rings, and practice staying seated through one ring: noticing the body, naming the urge, letting the sound fade. Log the ring''s length; most are shorter than they feel. Watch for the client who tries to disconnect the bell; the practice is not answering, not silencing.', '[{"id": "f0", "type": "textarea", "label": "What my urge doorbell sounds like, and how loud it gets:"}, {"id": "f1", "type": "textarea", "label": "What I usually do within the first minute of it ringing:"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my body while I stayed seated through a ring:"}, {"id": "f3", "type": "textarea", "label": "How long the ring lasted this time, compared with how long it felt:"}, {"id": "f4", "type": "textarea", "label": "What I did when it stopped:"}, {"id": "f5", "type": "textarea", "label": "Who I could call while it is ringing, before I go to the door:"}]'::jsonb, array['addiction', 'urges', 'defusion']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('burning-bridges-deleting-the-old-contacts-card', 'Burning Bridges Deleting the Old Contacts Card', 'dbt'::resource_kind, 'A DBT burning-bridges card for removing the numbers, apps and routes that lead back to substance use.', 'Use it to plan which bridges the client will close this week and what they will feel as each one goes.', array['Adults']::text[], 'One session, then one week', 'Burning bridges is the DBT addiction skill of actively cutting the links to use: contacts, apps, routes, hiding spots. The card lists the client''s bridges, which they will close this week and how (delete, block, change the route, tell someone), what they expect to feel as each goes, and what they will replace the bridge with. Do the first deletion in session; the rest are homework with a check-in. Watch for the client who keeps one number ''just in case''; ask what the case is and plan for it without the number.', '[{"id": "f0", "type": "textarea", "label": "The bridges I still have (contacts, apps, routes, places, hidden supplies):"}, {"id": "f1", "type": "textarea", "label": "The ones I will close this week, and exactly how:"}, {"id": "f2", "type": "textarea", "label": "What I expect to feel as each one goes:"}, {"id": "f3", "type": "textarea", "label": "The one I am tempted to keep, and the case I am keeping it for:"}, {"id": "f4", "type": "textarea", "label": "What replaces each bridge (a new contact, a new route, a plan for the case):"}, {"id": "f5", "type": "textarea", "label": "Who I will tell when they are all closed:"}]'::jsonb, array['addiction', 'urges', 'core DBT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('alcohol-free-hosting-plan-for-partners', 'Alcohol-Free Hosting Plan for Partners', 'couples'::resource_kind, 'A couples plan for hosting a gathering without alcohol when one partner is not drinking and the other is unsure how guests will take it.', 'Use it to let both partners plan the drinks, the explanation and the support so the hosting partner is not alone in it.', array['Couples']::text[], '30 minutes', 'Hosting without alcohol asks the couple to agree on something they may not have discussed: whether guests bring their own, what the house offers, who explains, and what the partner who is not drinking needs from the other during the evening. Each writes their hopes and worries, then the couple decides the drinks menu, the one-line explanation if anyone asks, who handles a guest who pushes, and the check-in during the evening. Watch for the drinking partner who feels their own choices are being judged; make that part of the sheet.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I need from this evening, and what I am worried about:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need from this evening, and what I am worried about:"}, {"id": "f2", "type": "textarea", "label": "What the house will offer to drink, and whether guests bring anything:"}, {"id": "f3", "type": "textarea", "label": "Our one-line explanation if anyone asks, and who says it:"}, {"id": "f4", "type": "textarea", "label": "Who handles a guest who pushes, and how:"}, {"id": "f5", "type": "textarea", "label": "Our check-in signal during the evening, and what happens if one of us needs to step away:"}]'::jsonb, array['addiction', 'couples', 'planning']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('cousin-who-baits-me-at-dinner-exit-plan-sheet', 'Cousin Who Baits Me at Dinner Exit Plan Sheet', 'worksheet'::resource_kind, 'A planning sheet for the relative who reliably provokes the client at the holiday table, and the exit they take instead of a blowup.', 'Use it to plan the first sign, the first move and the place the client goes, before the dinner starts.', array['Adults', 'Teens']::text[], '20 minutes before the gathering', 'Every family has someone who knows exactly which button to press, and the client has usually already lost that argument in their head. The sheet names the person, the bait they typically use, the client''s earliest body sign of heating up, the first move (a sip of water, a question to someone else), the exit line and the place they go for five minutes, and what they do if the person follows. Rehearse the exit line until it is flat and easy. Watch for the client who plans the perfect comeback; that is the opposite of the plan.', '[{"id": "f0", "type": "textarea", "label": "The person and the bait they usually use:"}, {"id": "f1", "type": "textarea", "label": "My earliest body sign that I am heating up:"}, {"id": "f2", "type": "textarea", "label": "My first move when I notice it (water, a question to someone else, a plate to carry):"}, {"id": "f3", "type": "textarea", "label": "My exit line, and the place I will go for five minutes:"}, {"id": "f4", "type": "textarea", "label": "What I will do if they follow me:"}, {"id": "f5", "type": "textarea", "label": "How I want to feel about myself driving home:"}]'::jsonb, array['anger management', 'de-escalation', 'planning']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('parking-spot-taken-means-they-did-it-on-purpose-sheet', 'Parking Spot Taken Means They Did It on Purpose Sheet', 'cbt'::resource_kind, 'A CBT sheet for the hostile read on strangers: the car that took the spot, the cart left in the way, the slow lane.', 'Use it to catch the intent the client assigns to strangers and generate the ordinary explanations they skipped.', array['Adults', 'Teens']::text[], '15 minutes, then one week', 'Anger in public often runs on mind reading: they saw me waiting, they knew, they did it on purpose. The sheet logs one incident, the intent the client assigned, how sure they were, three ordinary explanations (did not see, distracted, bad day), and what they would have felt under the most likely one. Done over a week it shows the pattern of assumed malice. Watch for the client who insists the stranger really did see them; even so, the sheet asks what else was true of that person''s day.', '[{"id": "f0", "type": "textarea", "label": "What happened, in plain facts:"}, {"id": "f1", "type": "textarea", "label": "The intent I assigned to the other person, and how sure I was (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "Three ordinary explanations I skipped:"}, {"id": "f3", "type": "textarea", "label": "The most likely explanation, and what I would have felt under it:"}, {"id": "f4", "type": "textarea", "label": "What I did in the moment, and what I would do under the most likely explanation:"}]'::jsonb, array['anger management', 'mind reading', 'thinking traps']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('anger-as-a-pot-lid-rattling-page', 'Anger as a Pot Lid Rattling Page', 'act'::resource_kind, 'An ACT page that treats rising anger as a pot lid starting to rattle: a signal to turn the heat down, not a disaster yet.', 'Use it to give a client a kitchen image for noticing anger early and choosing what to do with the heat.', array['Adults', 'Teens']::text[], '15 minutes, then one week', 'The lid rattles before the pot boils over, and most clients can learn to hear it. The page asks what the rattle is for them (jaw, voice, heat in the face), what is usually in the pot (the real grievance under the moment), what turning the heat down looks like (a step away, a breath, naming it), and what they value enough to keep the pot from boiling over onto. It is noticing and choosing, not suppressing. Watch for the client who wants to never rattle; the rattle is useful information.', '[{"id": "f0", "type": "textarea", "label": "My rattle: the earliest signs the lid is moving:"}, {"id": "f1", "type": "textarea", "label": "What is usually in the pot under today''s rattle:"}, {"id": "f2", "type": "textarea", "label": "What turning the heat down looks like for me, in two or three moves:"}, {"id": "f3", "type": "textarea", "label": "Who or what I value enough to keep the pot from boiling over onto:"}, {"id": "f4", "type": "textarea", "label": "A rattle this week, and what I did with the heat:"}]'::jsonb, array['anger management', 'metaphor', 'defusion']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-slamming-the-cabinet-doors-card', 'Opposite Action to Slamming the Cabinet Doors Card', 'dbt'::resource_kind, 'A DBT opposite-action card for the household anger that comes out as slammed doors, banged dishes and stomped stairs.', 'Use it to catch the urge to slam and act gently on purpose, noticing what the gentle action does to the anger.', array['Adults', 'Teens']::text[], 'Ten minutes, then one week', 'Slamming is anger''s shorthand at home: nobody gets hurt and everyone gets the message. Opposite action asks the client to close the cabinet slowly, set the dish down softly, speak at normal volume, when the anger does not fit the facts or acting on it will not help. The card logs the urge, the facts check, the opposite action taken all the way (body, face, voice), and what the anger did over the next ten minutes. Watch for the client who closes the door softly and then slams a sentence; opposite action includes the voice.', '[{"id": "f0", "type": "textarea", "label": "The moment I wanted to slam something, and what I wanted to slam:"}, {"id": "f1", "type": "textarea", "label": "Did the anger fit the facts, and would acting on it help? Short answer:"}, {"id": "f2", "type": "textarea", "label": "The opposite action I took, all the way (hands, face, voice):"}, {"id": "f3", "type": "textarea", "label": "What the anger did over the next ten minutes:"}, {"id": "f4", "type": "textarea", "label": "What the people in the house did differently, if anything:"}]'::jsonb, array['anger management', 'opposite action', 'core DBT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('anger-volume-knob-zero-to-ten-voice-game', 'Anger Volume Knob Zero to Ten Voice Game', 'game'::resource_kind, 'A group game in which players say the same neutral sentence at anger levels from zero to ten while others guess the number.', 'Use it to help a group hear their own escalation and practice turning the knob down on purpose.', array['Groups', 'Teens']::text[], '20 minutes', 'Rules: a facilitator gives a neutral sentence (the bus is late again). Each player draws a number from zero to ten and says the sentence at that level of anger; the group guesses the number. Round two: a player starts at eight and turns the knob down to three in three repetitions while the group watches what changes (volume, speed, jaw, hands). Debrief: what gave the level away, where each player''s normal setting sits, and what turning it down felt like from the inside. Watch for the member who cannot do a two; ask what a two sounds like in their house.', '[{"id": "f0", "type": "textarea", "label": "The number I drew, and what the group guessed:"}, {"id": "f1", "type": "textarea", "label": "What gave my level away (volume, speed, face, hands):"}, {"id": "f2", "type": "textarea", "label": "What it felt like to turn the knob from eight down to three:"}, {"id": "f3", "type": "textarea", "label": "Where my everyday setting sits, and who told me so:"}, {"id": "f4", "type": "textarea", "label": "One situation this week where I will try turning it down one notch:"}]'::jsonb, array['anger management', 'group', 'game']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('rewashing-the-serving-spoon-delay-log-sheet', 'Rewashing the Serving Spoon Delay Log Sheet', 'worksheet'::resource_kind, 'A delay log for the client who washes serving utensils again and again while cooking for others, afraid of making someone sick.', 'Use it to count the rewashes, delay each by a set time and record what the urge does while they wait.', array['Adults', 'Teens']::text[], 'One cooking day', 'Cooking for a crowd concentrates contamination fears: every spoon that touches the counter needs washing again. The sheet logs each urge to rewash, the delay the client holds (two minutes, then five), the urge''s strength at the start and end of the delay, and whether they rewashed. It is a delay log, not a ban; the client chooses the delay and keeps it. Watch for the client who delays and then rewashes everything at once at the end; log that too, without judgment, and look at the pattern together.', '[{"id": "f0", "type": "textarea", "label": "Each urge to rewash: the time, what triggered it, and how strong (0 to 10):"}, {"id": "f1", "type": "textarea", "label": "The delay I held before deciding, and how strong the urge was at the end of it:"}, {"id": "f2", "type": "textarea", "label": "Did I rewash? If so, how many times in total today:"}, {"id": "f3", "type": "textarea", "label": "What I did during the delays:"}, {"id": "f4", "type": "textarea", "label": "What I notice about how the urge behaves when I wait:"}, {"id": "f5", "type": "textarea", "label": "The delay I will try next time:"}]'::jsonb, array['OCD', 'checking', 'self-monitoring']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('thinking-it-means-i-will-do-it-while-cooking-check-sheet', 'Thinking It Means I Will Do It While Cooking Check Sheet', 'cbt'::resource_kind, 'A CBT sheet for the client whose intrusive thought near a knife or a stove feels like a prediction of what they will do.', 'Use it to examine thought-action fusion and separate having a thought from wanting or doing anything.', array['Adults', 'Teens']::text[], '20 minutes, in session', 'Intrusive thoughts near sharp or hot things are common and frightening, and the client often reads the thought as intent. The sheet names the thought in general terms, rates how much it feels like a prediction, counts the times it has arrived and nothing happened, and notes what the client actually wants in those moments (to protect, not harm). Do it in session, not as homework. If a thought touches on self-harm, 988 (call or text) is on the sheet and you review safety in the room. Watch for the client who avoids the kitchen altogether; that is the next thing to work on.', '[{"id": "f0", "type": "textarea", "label": "The thought, in general terms, without the details:"}, {"id": "f1", "type": "textarea", "label": "How much it feels like a prediction, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "How many times this thought has arrived, and how many times anything happened:"}, {"id": "f3", "type": "textarea", "label": "What I actually want in those moments (to protect, to get away, to be sure):"}, {"id": "f4", "type": "textarea", "label": "What I have started avoiding because of the thought:"}, {"id": "f5", "type": "textarea", "label": "If a thought is ever about hurting myself, I can call or text 988. Who I would tell first:"}]'::jsonb, array['OCD', 'thought-action fusion', 'intrusive thoughts']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('doubt-as-a-backseat-driver-i-do-not-obey-page', 'Doubt as a Backseat Driver I Do Not Obey Page', 'act'::resource_kind, 'An ACT defusion page in which the client''s doubting voice is a backseat driver: free to comment, not holding the wheel.', 'Use it to help a client keep driving toward what matters while the doubt keeps talking.', array['Adults', 'Teens']::text[], 'Ten minutes daily for one week', 'Doubt gives directions constantly: check again, go back, you are not sure. The backseat driver image lets the client hear it without obeying it. The page has them log the backseat driver''s comments during one activity a day, where they kept driving anyway, and what the driver did when ignored (usually got louder, then quieter). The wheel stays in the client''s hands; the passenger is allowed to ride. Watch for the client who pulls over to argue with the passenger; arguing is still obeying.', '[{"id": "f0", "type": "textarea", "label": "What my backseat driver said today, in its own words:"}, {"id": "f1", "type": "textarea", "label": "Where I was trying to go (the task, the plan, the value):"}, {"id": "f2", "type": "textarea", "label": "Where I kept driving anyway, and what that took:"}, {"id": "f3", "type": "textarea", "label": "What the driver did when I did not obey (louder, quieter, changed the subject):"}, {"id": "f4", "type": "textarea", "label": "One drive this week I will take with the passenger talking the whole way:"}]'::jsonb, array['OCD', 'defusion', 'metaphor']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('turning-the-mind-from-the-perfect-table-setting-card', 'Turning the Mind From the Perfect Table Setting Card', 'dbt'::resource_kind, 'A DBT turning-the-mind card for the client whose need to set the holiday table exactly right swallows the hours before guests arrive.', 'Use it to practice choosing acceptance of good enough, again and again, as the urge to fix returns.', array['Adults', 'Teens']::text[], 'One afternoon', 'Turning the mind is the DBT practice of choosing acceptance each time the mind turns back toward fighting reality. For a client who straightens every fork and re-folds every napkin, the reality to accept is a table that is good enough and a clock that is moving. The card sets a stopping time, logs each urge to fix after it, the choice made, and the phrase used to turn back toward the evening. Watch for the client who hits the stopping time and then rearranges from their seat; the practice is the repeated turn, and that counts too.', '[{"id": "f0", "type": "textarea", "label": "My stopping time for the table, and what good enough looks like:"}, {"id": "f1", "type": "textarea", "label": "Each urge to fix after the stopping time: what, and how strong:"}, {"id": "f2", "type": "textarea", "label": "The phrase I use to turn my mind back toward the evening:"}, {"id": "f3", "type": "textarea", "label": "How many times I turned the mind this afternoon:"}, {"id": "f4", "type": "textarea", "label": "What I was able to notice about the guests instead of the table:"}]'::jsonb, array['OCD', 'turning the mind', 'perfectionism']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('maybe-monster-sock-puppet-craft', 'Maybe Monster Sock Puppet Craft', 'kids'::resource_kind, 'A craft in which a child makes a sock puppet who only ever says maybe, and practices answering its questions without being sure.', 'Use it to give a child a playful way to meet uncertainty when their mind demands to know for certain.', array['Children']::text[], '30 minutes', 'A child who needs to be sure (did I lock it, is it clean, will it happen) can meet uncertainty through a puppet who never is. The child decorates an old sock with eyes and a wobbly mouth, names it, and the Maybe Monster asks the child''s own worry questions; the child practices answering ''maybe, and I am going to play anyway''. The parent voices the puppet first so the child hears a grown-up tolerate a maybe. Keep it silly. Watch for the child who wants the puppet to promise; the monster does not promise, and that is its whole job.', '[{"id": "f0", "type": "textarea", "label": "My Maybe Monster''s name, and what it looks like:"}, {"id": "f1", "type": "textarea", "label": "A question my monster asked me today:"}, {"id": "f2", "type": "textarea", "label": "What I said back (maybe, and...):"}, {"id": "f3", "type": "textarea", "label": "What my grown-up said when the monster asked them something:"}, {"id": "f4", "type": "textarea", "label": "How my body felt saying maybe, and what I did next:"}]'::jsonb, array['OCD', 'children', 'uncertainty']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('hot-crowded-kitchen-heat-flush-log-sheet', 'Hot Crowded Kitchen Heat Flush Log Sheet', 'worksheet'::resource_kind, 'A log sheet for the client whose face flushes and heart races in a hot, crowded kitchen and who reads it as the start of a panic attack.', 'Use it to log the sensations, their ordinary causes and what happened when the client stayed instead of fleeing.', array['Adults', 'Teens']::text[], 'One gathering', 'An oven, a crowd and a sweater make everyone hot, and for a client with panic the heat reads as danger. The sheet logs each flush: where they were, the sensations, the panic thought, the ordinary causes present (oven, bodies, wool, wine), what they did, and how long the sensations lasted. Staying in the kitchen with a glass of cold water is the aim, not leaving. Watch for the client who logs everything from the porch; the log is for the room where it happens.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what was going on when the heat hit:"}, {"id": "f1", "type": "textarea", "label": "The sensations, in order, and how strong they got:"}, {"id": "f2", "type": "textarea", "label": "The panic thought that arrived with them:"}, {"id": "f3", "type": "textarea", "label": "Ordinary causes of heat present at the time (oven, crowd, sweater, drink):"}, {"id": "f4", "type": "textarea", "label": "What I did, and how long the sensations lasted:"}, {"id": "f5", "type": "textarea", "label": "What I will try next time the kitchen heats up:"}]'::jsonb, array['panic attacks', 'sensations', 'self-monitoring']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('dizzy-standing-up-means-i-will-faint-fact-check-sheet', 'Dizzy Standing Up Means I Will Faint Fact Check Sheet', 'cbt'::resource_kind, 'A CBT fact-check sheet for the lightheaded moment after standing up fast that the client reads as imminent fainting.', 'Use it to compare the client''s prediction with what actually happens to blood pressure during panic and after standing.', array['Adults', 'Teens']::text[], '15 minutes', 'Lightheadedness on standing is ordinary, and in panic the body''s rising blood pressure makes fainting less likely, not more, yet the prediction persists. The sheet records the moment, the prediction and its certainty, how many times the client has felt this and how many times they have fainted, what they did with the dizziness (sat down, gripped something), and a plain fact sentence to carry. Add a standing-up-fast practice if the client is willing. Watch for the client with a real history of fainting; check with their physician before any practice.', '[{"id": "f0", "type": "textarea", "label": "The moment: what I was doing when the dizziness hit:"}, {"id": "f1", "type": "textarea", "label": "My prediction, and how certain I felt (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "How many times I have felt this, and how many times I have actually fainted:"}, {"id": "f3", "type": "textarea", "label": "What I did with the dizziness, and how long it took to pass:"}, {"id": "f4", "type": "textarea", "label": "A plain fact sentence I can carry about dizziness and panic:"}, {"id": "f5", "type": "textarea", "label": "Whether I am willing to practice standing up fast on purpose this week, and when:"}]'::jsonb, array['panic attacks', 'fact check', 'sensations']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('panic-as-a-smoke-machine-at-a-concert-page', 'Panic as a Smoke Machine at a Concert Page', 'act'::resource_kind, 'An ACT page in which panic is a smoke machine: dramatic, hard to see through, and producing no fire at all.', 'Use it to help a client let the smoke roll through without searching for the fire that is not there.', array['Adults', 'Teens']::text[], '15 minutes, then as needed', 'A smoke machine fills the room, stings the eyes and sets off everyone''s instincts, and there is nothing burning. The page asks the client to describe their smoke (which sensations), what they usually do when it starts (search for the fire, run for the exit), and to practice standing in it: naming it as smoke, breathing normally, letting it thin on its own. Log how long the smoke took to clear when they did not run. Watch for the client who wants to find the switch and turn it off; the machine runs on its own schedule, and the practice is staying.', '[{"id": "f0", "type": "textarea", "label": "My smoke: the sensations that roll in first:"}, {"id": "f1", "type": "textarea", "label": "What I usually do when the smoke starts (look for the fire, head for the exit, check my pulse):"}, {"id": "f2", "type": "textarea", "label": "What I did this time instead, and what the smoke did:"}, {"id": "f3", "type": "textarea", "label": "How long it took to thin when I stayed:"}, {"id": "f4", "type": "textarea", "label": "What I could see once it cleared that I had missed while searching for fire:"}]'::jsonb, array['panic attacks', 'acceptance', 'metaphor']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('paced-breathing-in-the-dressing-room-line-card', 'Paced Breathing in the Dressing Room Line Card', 'dbt'::resource_kind, 'A DBT paced-breathing card for the long, hot line outside a store dressing room during holiday shopping.', 'Use it to give a client a breath pattern they can run standing in line without anyone noticing.', array['Adults', 'Teens']::text[], 'Five minutes, as needed', 'Lines are a panic setting: no exit without losing a place, heat, bodies, nothing to do but notice the heart. Paced breathing (a longer out-breath than in-breath, five or six breaths a minute) is invisible and portable. The card plans the count (in for four, out for six), what the eyes rest on, a hand position that helps, and logs the body before and after. Practice in session first, then in a short line before a long one. Watch for the client who breathes deeply and fast; the pace is slow, and the out-breath is the point.', '[{"id": "f0", "type": "textarea", "label": "My count: in for how long, out for how long:"}, {"id": "f1", "type": "textarea", "label": "Where my eyes rest while I breathe in a line:"}, {"id": "f2", "type": "textarea", "label": "What my hands do:"}, {"id": "f3", "type": "textarea", "label": "How my body was before the breathing, 0 to 10, and after three minutes:"}, {"id": "f4", "type": "textarea", "label": "Which line I will practice in this week, and how long I stayed:"}]'::jsonb, array['panic attacks', 'paced breathing', 'core DBT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('stair-climb-heartbeat-guessing-game', 'Stair Climb Heartbeat Guessing Game', 'game'::resource_kind, 'A group game in which players climb a flight of stairs, guess their heart rate, then count it and watch it settle.', 'Use it to help a group see a racing heart as a number that climbs and falls, not a signal of catastrophe.', array['Groups', 'Teens']::text[], '20 minutes', 'Rules: players climb one flight of stairs at a brisk pace (anyone with a heart or joint condition sits out or walks slowly). At the top each guesses their heart rate, then counts their pulse for fifteen seconds and multiplies by four. Everyone sits and counts again at one, two and three minutes while the group calls out numbers. Debrief: how far off the guesses were, what the drop felt like, and what the group thinks when a heart races without stairs. Watch for the member whose guess is far above the count; that gap is the lesson.', '[{"id": "f0", "type": "textarea", "label": "My guess at the top of the stairs, and my actual count:"}, {"id": "f1", "type": "textarea", "label": "My counts at one, two and three minutes:"}, {"id": "f2", "type": "textarea", "label": "What it felt like in my body as the number dropped:"}, {"id": "f3", "type": "textarea", "label": "What I usually think when my heart races without any stairs:"}, {"id": "f4", "type": "textarea", "label": "One thing from the numbers I want to remember next time it races:"}]'::jsonb, array['panic attacks', 'group', 'interoceptive']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('long-weekend-loose-routine-anchors-sheet', 'Long Weekend Loose Routine Anchors Sheet', 'worksheet'::resource_kind, 'A parent planning sheet for a long holiday weekend when the usual routine is gone and the kids unravel by day two.', 'Use it to pick three daily anchors that stay fixed while everything else is allowed to be loose.', array['Adults']::text[], '15 minutes before the weekend', 'A long weekend with no school, late nights and relatives undoes a child''s rhythm, and the parent spends day three managing meltdowns. The sheet asks the parent to choose three anchors that do not move (wake time within an hour, one meal at the table, bedtime ritual), what is deliberately allowed to be loose, who holds the anchors when the parent is busy, and what they will say when a child protests. Fewer anchors, held firmly, work better than a full schedule. Watch for the parent who writes eight anchors; cut to three.', '[{"id": "f0", "type": "textarea", "label": "The three anchors that stay fixed this weekend:"}, {"id": "f1", "type": "textarea", "label": "What is deliberately allowed to be loose:"}, {"id": "f2", "type": "textarea", "label": "Who holds the anchors when I am cooking, hosting or away:"}, {"id": "f3", "type": "textarea", "label": "What I will say when a child protests an anchor:"}, {"id": "f4", "type": "textarea", "label": "How I will know by Sunday whether the anchors held:"}]'::jsonb, array['parenting', 'routines', 'planning']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('toddler-meltdown-in-public-means-everyone-is-judging-sheet', 'Toddler Meltdown in Public Means Everyone Is Judging Sheet', 'cbt'::resource_kind, 'A CBT sheet for the parent whose child''s public tantrum becomes a certainty that every stranger in the store is judging them.', 'Use it to catch the mind reading, estimate what strangers actually think and plan what the parent will do in the moment.', array['Adults']::text[], '15 minutes', 'A toddler on the floor of the grocery store is loud, and the parent''s mind fills the aisle with critics. The sheet records the moment, the thoughts the parent assigned to strangers, how sure they were, what they themselves think when they see another parent''s child melt down, and what the child needed in the moment that the imagined audience pulled them from. End with a plan for the next public meltdown that is about the child, not the crowd. Watch for the parent who did receive a comment; one stranger is not the store.', '[{"id": "f0", "type": "textarea", "label": "What happened, where, and how long it lasted:"}, {"id": "f1", "type": "textarea", "label": "The thoughts I assigned to the people around us:"}, {"id": "f2", "type": "textarea", "label": "How sure I was, 0 to 100, and what I actually saw people do:"}, {"id": "f3", "type": "textarea", "label": "What I think when I see another parent''s child melt down in public:"}, {"id": "f4", "type": "textarea", "label": "What my child needed in that moment:"}, {"id": "f5", "type": "textarea", "label": "My plan for the next public meltdown, in three steps:"}]'::jsonb, array['parenting', 'mind reading', 'thinking traps']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('willing-to-be-the-unpopular-parent-tonight-page', 'Willing to Be the Unpopular Parent Tonight Page', 'act'::resource_kind, 'An ACT willingness page for the parent who holds a limit at a family gathering while relatives and children push back.', 'Use it to connect the unpopular limit to a value and make room for being disliked for an evening.', array['Adults']::text[], '15 minutes before the gathering', 'Holding a bedtime or a screen rule in front of grandparents who disagree asks the parent to be, briefly, the least popular person in the room. The page names the limit, the value under it, who will push back and how, what the parent is willing to feel (disapproval, a sulking child, a sigh from a relative), and the sentence they will say when they hold it. Willingness here is not stubbornness; the limit should be one that matters. Watch for the parent who picks three limits; one is enough for a night.', '[{"id": "f0", "type": "textarea", "label": "The one limit I am holding tonight:"}, {"id": "f1", "type": "textarea", "label": "The value under it, in my own words:"}, {"id": "f2", "type": "textarea", "label": "Who will push back, and how:"}, {"id": "f3", "type": "textarea", "label": "What I am willing to feel to hold it:"}, {"id": "f4", "type": "textarea", "label": "The sentence I will say when I hold it, kindly and once:"}, {"id": "f5", "type": "textarea", "label": "What I will do for myself after the kids are down:"}]'::jsonb, array['parenting', 'willingness', 'values']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('dear-man-asking-the-teen-to-join-dinner-card', 'DEAR MAN Asking the Teen to Join Dinner Card', 'dbt'::resource_kind, 'A DBT DEAR MAN card for the parent asking a teenager to leave their room and join the family table without a standoff.', 'Use it to script a clear, respectful request that names what the parent wants and what the teen gets.', array['Adults']::text[], '15 minutes', 'The nightly dinner standoff has a script the parent knows by heart, and it does not work. DEAR MAN (Describe, Express, Assert, Reinforce, stay Mindful, Appear confident, Negotiate) gives a different one. The card drafts each step: the fact (you have eaten in your room four nights), the feeling (I miss you), the ask (join us three nights a week), the reinforcement (you pick the music, we skip the grades talk), and the negotiation the parent is actually open to. Rehearse the tone in session. Watch for the parent whose Express is a complaint; it should be a feeling.', '[{"id": "f0", "type": "textarea", "label": "Describe: the facts, without blame:"}, {"id": "f1", "type": "textarea", "label": "Express: how I feel about it, as a feeling and not a verdict:"}, {"id": "f2", "type": "textarea", "label": "Assert: exactly what I am asking for:"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what my teen gets out of saying yes:"}, {"id": "f4", "type": "textarea", "label": "Mindful and confident: how I will stay on track when they argue, and what my voice will sound like:"}, {"id": "f5", "type": "textarea", "label": "Negotiate: what I am actually willing to settle for:"}]'::jsonb, array['parenting', 'DEAR MAN', 'communication']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('thankful-pumpkin-seed-count-jar-craft', 'Thankful Pumpkin Seed Count Jar Craft', 'kids'::resource_kind, 'A craft in which a family drops a pumpkin seed in a jar for every good thing someone names, and watches it fill across the week.', 'Use it to give a parent a daily, visible gratitude habit a child can run with their hands.', array['Children']::text[], 'Ten minutes daily for one week', 'A clear jar, a bag of dried pumpkin seeds and a marker on the lid make a gratitude practice a child can see grow. At dinner or bedtime each person names one good thing from the day and drops in a seed; the child is the keeper of the jar. The parent goes first and names something small and true, and asks one follow-up question about the child''s seed. At the end of the week the family counts the seeds together. Watch for the parent who uses the jar to prompt thankfulness as a correction; it is a game, not a lesson.', '[{"id": "f0", "type": "textarea", "label": "How many seeds are in the jar tonight:"}, {"id": "f1", "type": "textarea", "label": "The good thing I named today:"}, {"id": "f2", "type": "textarea", "label": "The good thing my grown-up named, and the question they asked me:"}, {"id": "f3", "type": "textarea", "label": "A seed someone else dropped in that I liked hearing about:"}, {"id": "f4", "type": "textarea", "label": "What we will do with the seeds at the end of the week:"}]'::jsonb, array['parenting', 'children', 'gratitude']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('relatives-passing-the-baby-around-limits-sheet', 'Relatives Passing the Baby Around Limits Sheet', 'worksheet'::resource_kind, 'A planning sheet for a new parent whose baby will be passed around a crowded gathering and who wants limits without a scene.', 'Use it to decide in advance who holds the baby, for how long, and the words that bring the baby back.', array['Adults']::text[], '15 minutes before the gathering', 'A new parent at a big gathering watches their baby go from arm to arm and feels both rude and frantic. The sheet decides the limits beforehand: who may hold the baby, the signs that it is time to come back (fussing, feeding time, the parent''s own pulse), the plain sentence that retrieves the baby, and a partner or friend who will run the retrieval if the parent cannot. The limits are the parent''s to set, and no explanation is owed. Watch for the parent who apologizes in every line; cut the apologies and keep the sentences.', '[{"id": "f0", "type": "textarea", "label": "Who may hold the baby today, and anyone who may not:"}, {"id": "f1", "type": "textarea", "label": "The signs that it is time for the baby to come back to me:"}, {"id": "f2", "type": "textarea", "label": "The plain sentence I will use to take the baby back:"}, {"id": "f3", "type": "textarea", "label": "Who will help me retrieve the baby if I cannot do it myself:"}, {"id": "f4", "type": "textarea", "label": "Where I can go with the baby to feed or settle, and who knows that:"}, {"id": "f5", "type": "textarea", "label": "What I will tell myself if a relative is put out:"}]'::jsonb, array['perinatal and postpartum', 'boundaries', 'planning']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('not-enjoying-every-moment-means-i-am-ungrateful-sheet', 'Not Enjoying Every Moment Means I Am Ungrateful Sheet', 'cbt'::resource_kind, 'A CBT sheet for the new parent told to enjoy every moment who feels like a failure when a moment is only hard.', 'Use it to separate gratitude from constant enjoyment and let hard hours be hard without a verdict.', array['Adults']::text[], '20 minutes', 'Strangers and relatives tell new parents to enjoy every moment, and the parent who is exhausted at 3 a.m. hears it as an accusation. The sheet records the should, the moment that did not feel enjoyable, the thought about the self that followed, what else was true in that moment (love and exhaustion at once), and what a wise friend who had been through it would say. Then it asks for a moment this week that was actually good, kept small. Watch for the parent who cannot find a good moment at all; that deserves a wider look at how they are doing.', '[{"id": "f0", "type": "textarea", "label": "The should I keep hearing about enjoying every moment, and who says it:"}, {"id": "f1", "type": "textarea", "label": "A moment this week that was only hard:"}, {"id": "f2", "type": "textarea", "label": "The thought about me that followed:"}, {"id": "f3", "type": "textarea", "label": "What else was true in that moment (both things at once):"}, {"id": "f4", "type": "textarea", "label": "What a friend who has been through this would say to me:"}, {"id": "f5", "type": "textarea", "label": "One moment this week that was actually good, however small:"}]'::jsonb, array['perinatal and postpartum', 'should statements', 'guilt']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('worried-parent-mind-as-an-overzealous-lifeguard-page', 'Worried Parent Mind as an Overzealous Lifeguard Page', 'act'::resource_kind, 'An ACT defusion page in which the new parent''s constant alarm is a lifeguard who blows the whistle at every ripple.', 'Use it to let a parent thank the lifeguard, check the water and get back to the baby without obeying every whistle.', array['Adults']::text[], 'Ten minutes, then one week', 'A new parent''s mind guards a baby with a whistle that never stops: is that breath normal, is the room too warm, did I buckle it right. The lifeguard image honors the job and loosens the grip. The page logs the whistles for a day, which were ripples and which were worth a look, a short acknowledgment phrase, and what the parent went back to doing. It is not reassurance; the lifeguard stays on duty. Watch for a parent whose whistles are relentless and sleepless; check how they are sleeping and whether they need more than this page.', '[{"id": "f0", "type": "textarea", "label": "The whistles my lifeguard blew today, briefly:"}, {"id": "f1", "type": "textarea", "label": "Which were ripples, and which were worth a real look:"}, {"id": "f2", "type": "textarea", "label": "My acknowledgment phrase for the lifeguard:"}, {"id": "f3", "type": "textarea", "label": "What I went back to doing with the baby while the whistle faded:"}, {"id": "f4", "type": "textarea", "label": "What I notice about the whistles at the end of the week:"}]'::jsonb, array['perinatal and postpartum', 'defusion', 'metaphor']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('self-soothe-in-the-nursing-chair-five-senses-card', 'Self-Soothe in the Nursing Chair Five Senses Card', 'dbt'::resource_kind, 'A DBT self-soothe card for the long night feeds, one small comfort for each sense within reach of the chair.', 'Use it to turn the feeding chair into a place with a prepared comfort for each sense, ready before the night starts.', array['Adults']::text[], 'Ten minutes to set up, then each night', 'Night feeds are long, repeated and lonely, and the parent often sits in the dark with only the phone. The card prepares the chair: something to see (a dim lamp, a photo), hear (a quiet playlist, a podcast), smell (a lotion, the baby), touch (a soft blanket, a warm mug), taste (water, a mint). The parent sets it up before bed and logs what helped at 3 a.m. It is comfort for the parent, not the baby. Watch for the parent who feels the comforts are indulgent; the sheet is the permission.', '[{"id": "f0", "type": "textarea", "label": "See: what I will have in view from the chair:"}, {"id": "f1", "type": "textarea", "label": "Hear: what I will listen to, and how I will start it with one hand:"}, {"id": "f2", "type": "textarea", "label": "Smell and touch: what is within reach:"}, {"id": "f3", "type": "textarea", "label": "Taste: what is on the side table:"}, {"id": "f4", "type": "textarea", "label": "Which comfort helped most at 3 a.m., and which I will change:"}]'::jsonb, array['perinatal and postpartum', 'self-soothing', 'core DBT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('first-holiday-trip-with-the-baby-packing-split-for-partners', 'First Holiday Trip With the Baby Packing Split for Partners', 'couples'::resource_kind, 'A couples sheet for the first trip with a newborn, splitting the packing, the car and the relatives before the drive.', 'Use it to let both partners write what they dread about the trip and divide the load before resentment packs itself.', array['Couples']::text[], '30 minutes, a few days before', 'The first trip with a baby is a hundred small tasks and two tired people who each think they are doing most of them. Each partner writes what they are dreading and what they assume the other will handle, then the couple divides packing, the car setup, the feeding and changing plan on the road, who manages which relatives on arrival, and the signal for a break. The dread columns are read aloud to each other first. Watch for the partner who takes every item to keep the peace; the split should be defensible to a stranger.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I am dreading about this trip, and what I assume you will handle:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I am dreading about this trip, and what I assume you will handle:"}, {"id": "f2", "type": "textarea", "label": "Who packs what, with a list for each of us:"}, {"id": "f3", "type": "textarea", "label": "The car: who drives, who sits with the baby, and the plan for feeds and changes on the road:"}, {"id": "f4", "type": "textarea", "label": "On arrival: who manages which relatives, and where the baby''s quiet room is:"}, {"id": "f5", "type": "textarea", "label": "Our signal for needing a break, and what the other does when they see it:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'fairness']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('things-i-did-well-at-the-gathering-receipt-sheet', 'Things I Did Well at the Gathering Receipt Sheet', 'worksheet'::resource_kind, 'A post-event sheet for the client who leaves every gathering with a list of their failures and no record of what went fine.', 'Use it to collect an itemized receipt of what the client did well before the critic rewrites the evening.', array['Adults', 'Teens']::text[], 'Ten minutes, the same night', 'The ride home from a gathering is where a client with low self-worth rewrites the evening into a catalog of missteps. The receipt sheet is filled out before bed: five things they did that were fine or good (showed up, asked a question, helped carry something), one thing they would do differently stated once, who seemed glad to see them, and what the critic is saying versus what the receipt says. The receipt is evidence; the critic is a voice. Watch for the client who cannot reach five items; start with showed up and build from there.', '[{"id": "f0", "type": "textarea", "label": "Five things I did tonight that were fine or good, however small:"}, {"id": "f1", "type": "textarea", "label": "One thing I would do differently, said once and then left alone:"}, {"id": "f2", "type": "textarea", "label": "Who seemed glad to see me, and how I could tell:"}, {"id": "f3", "type": "textarea", "label": "What my critic is saying about tonight:"}, {"id": "f4", "type": "textarea", "label": "What the receipt says instead:"}, {"id": "f5", "type": "textarea", "label": "The one item I will remember tomorrow:"}]'::jsonb, array['self-esteem', 'strengths', 'self-monitoring']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('not-invited-to-the-friendsgiving-means-i-am-unlikable-sheet', 'Not Invited to the Friendsgiving Means I Am Unlikable Sheet', 'cbt'::resource_kind, 'A CBT sheet for the client who was left off one guest list and concluded something permanent about themselves.', 'Use it to catch the labeling, widen the explanations for one omission and look at the client''s whole social picture.', array['Adults', 'Teens']::text[], '20 minutes', 'One missing invitation can carry a whole self-concept for a client who already suspects they are not wanted. The sheet names the label, the single event it rests on, the explanations other than unlikability (space, an oversight, a smaller group, a host who is overwhelmed), the client''s other invitations and friendships this year, and what they would say to a friend who drew the same conclusion from one party. Then a plan: ask, reach out to someone else, or let it be. Watch for the client who lists their other friendships as pity invitations; that discounting is the next sheet.', '[{"id": "f0", "type": "textarea", "label": "The label I gave myself when I found out:"}, {"id": "f1", "type": "textarea", "label": "Exactly what happened, in facts (who, what, how I found out):"}, {"id": "f2", "type": "textarea", "label": "Explanations other than the label (space, oversight, a small group, a stressed host):"}, {"id": "f3", "type": "textarea", "label": "My other invitations and friendships this year, listed honestly:"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend who concluded this from one party:"}, {"id": "f5", "type": "textarea", "label": "What I will do: ask, reach out to someone else, or let it be, and why:"}]'::jsonb, array['self-esteem', 'labeling', 'thinking traps']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('self-worth-as-the-table-not-the-dishes-on-it-page', 'Self-Worth as the Table Not the Dishes on It Page', 'act'::resource_kind, 'An ACT self-as-context page in which the client''s worth is the table that holds every success and failure, not the dishes themselves.', 'Use it to help a client experience a steady sense of self that is not raised or lowered by the latest result.', array['Adults', 'Teens']::text[], '15 minutes, then one week', 'A client whose worth rises and falls with each outcome is treating the dishes as the table. The page asks them to list this week''s dishes (a compliment, a mistake, a win, a snub), notice how each one moved their sense of worth, then describe the table: the one that was there before the dishes arrived and will be there after they are cleared. The table does not get better or worse because a dish broke. Watch for the client who wants the table to be made of their achievements; that is a very tall stack of dishes, and the page asks what is under it.', '[{"id": "f0", "type": "textarea", "label": "This week''s dishes: the results, comments and moments that landed on me:"}, {"id": "f1", "type": "textarea", "label": "How much each one moved my sense of worth, up or down:"}, {"id": "f2", "type": "textarea", "label": "The table: what was there before these dishes, and will be there after:"}, {"id": "f3", "type": "textarea", "label": "What it is like to notice that the table did not change when a dish broke:"}, {"id": "f4", "type": "textarea", "label": "One dish I will let be cleared this week without deciding it was about the table:"}]'::jsonb, array['self-esteem', 'self-as-context', 'metaphor']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('fast-skill-when-asked-to-host-again-card', 'FAST Skill When Asked to Host Again Card', 'dbt'::resource_kind, 'A DBT FAST card for the client who hosts every year because saying no feels like failing the family.', 'Use it to script a refusal or a renegotiation that keeps the client''s self-respect intact.', array['Adults']::text[], '15 minutes', 'FAST (be Fair, no Apologies, Stick to values, be Truthful) is for the moments when saying yes would cost the client their self-respect. Hosting again when they are depleted is one of them. The card scripts a fair ask (a rotation, a potluck, a different house), removes the apologies the client reflexively adds, names the value they are protecting (rest, honesty, fairness), and keeps the reason truthful rather than inventing a conflict. Rehearse it without a single sorry. Watch for the client who writes ''I know it is selfish but''; cut it.', '[{"id": "f0", "type": "textarea", "label": "Fair: what I am proposing instead, fair to me and to them:"}, {"id": "f1", "type": "textarea", "label": "No apologies: my script, with every sorry crossed out:"}, {"id": "f2", "type": "textarea", "label": "Stick to values: the value I am protecting by not hosting this year:"}, {"id": "f3", "type": "textarea", "label": "Truthful: the real reason, said plainly:"}, {"id": "f4", "type": "textarea", "label": "What I will do if they push, in one sentence:"}, {"id": "f5", "type": "textarea", "label": "How I want to feel about myself after the call:"}]'::jsonb, array['self-esteem', 'FAST', 'interpersonal effectiveness']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('good-rumor-pass-around-the-circle-game', 'Good Rumor Pass Around the Circle Game', 'game'::resource_kind, 'A circle game in which each player whispers a true good thing about the next person, and the rumors travel around the room.', 'Use it to let a group hear specific good things about themselves secondhand, which is often easier to take in than praise to the face.', array['Groups', 'Teens']::text[], '20 minutes', 'Rules: players sit in a circle. Each whispers to the person on their right one true, specific good thing about the person on their left (a strength they have seen, something they did in group). The receiver passes the rumor on to the next person, who passes it on again, until it reaches its subject as ''I heard that you...''. Then reverse direction with a new round. Debrief: what it was like to hear a good rumor about yourself, what the group noticed about who deflected, and which rumor someone wants to keep. Watch for jokes; set the rule that every rumor is kind and true.', '[{"id": "f0", "type": "textarea", "label": "The good rumor that reached me, in the words it arrived in:"}, {"id": "f1", "type": "textarea", "label": "What my body did when I heard it:"}, {"id": "f2", "type": "textarea", "label": "The rumor I started about someone, and whether it was easy or hard to think of:"}, {"id": "f3", "type": "textarea", "label": "What I did with the rumor: took it in, laughed it off, argued:"}, {"id": "f4", "type": "textarea", "label": "The rumor I am keeping this week:"}]'::jsonb, array['self-esteem', 'group', 'game']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('arriving-at-the-potluck-alone-first-five-minutes-sheet', 'Arriving at the Potluck Alone First Five Minutes Sheet', 'worksheet'::resource_kind, 'A planning sheet for the first five minutes after a client walks into a gathering alone, when they usually hover by the door or leave.', 'Use it to script the entry, the dish drop-off and the first conversation so the hardest minutes have a plan.', array['Adults', 'Teens']::text[], '15 minutes before the event', 'The first five minutes decide whether the client stays, and they are the minutes with no plan. The sheet scripts them: what they say to the host at the door, where the dish goes, the first thing they do with their hands (a drink, a plate), the first person they approach and the question they ask, and the point at which they allow themselves to decide about staying (not before twenty minutes). Rehearse the first question aloud. Watch for the client whose plan is to find the one person they know and never leave them; add one stranger to the plan.', '[{"id": "f0", "type": "textarea", "label": "What I will say to the host in the first thirty seconds:"}, {"id": "f1", "type": "textarea", "label": "Where the dish or drink I brought goes, and what I do with my hands after:"}, {"id": "f2", "type": "textarea", "label": "The first person I will approach, and the question I will ask them:"}, {"id": "f3", "type": "textarea", "label": "One stranger I will say one thing to before I decide anything:"}, {"id": "f4", "type": "textarea", "label": "The earliest time I am allowed to decide about leaving:"}, {"id": "f5", "type": "textarea", "label": "What I will say to myself at the door if I want to turn around:"}]'::jsonb, array['social anxiety', 'planning', 'avoidance']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('everyone-saw-me-spill-the-gravy-spotlight-sheet', 'Everyone Saw Me Spill the Gravy Spotlight Sheet', 'cbt'::resource_kind, 'A CBT spotlight-effect sheet for the client who spilled something at the table and is sure the whole room is still thinking about it.', 'Use it to estimate how many people noticed, how long they thought about it and what else they were attending to.', array['Adults', 'Teens']::text[], '15 minutes', 'The spotlight effect makes a small spill feel like a headline. The sheet records the incident, the client''s estimate of how many people noticed and for how long, what everyone else was busy with (their own plate, their own conversation, their own worries), the last time the client noticed someone else''s spill and how long they thought about it, and a revised estimate. Done after a real event it lands harder than theory. Watch for the client who insists someone laughed; one laugh at a spill is a reaction, not a verdict.', '[{"id": "f0", "type": "textarea", "label": "What I spilled, dropped or knocked over, and where:"}, {"id": "f1", "type": "textarea", "label": "How many people I think noticed, and for how long:"}, {"id": "f2", "type": "textarea", "label": "What everyone else at the table was busy with at the time:"}, {"id": "f3", "type": "textarea", "label": "The last time I saw someone else spill, and how long I thought about it:"}, {"id": "f4", "type": "textarea", "label": "My revised estimate of who noticed and how long it stayed with them:"}, {"id": "f5", "type": "textarea", "label": "What I will do next time something spills, in the first ten seconds:"}]'::jsonb, array['social anxiety', 'spotlight effect', 'thinking traps']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('making-room-for-awkward-silence-at-the-table-page', 'Making Room for Awkward Silence at the Table Page', 'act'::resource_kind, 'An ACT willingness page for the client who fills every pause with talk or flight, practicing letting a silence sit.', 'Use it to help a client tolerate a conversational gap without treating it as proof they have failed socially.', array['Adults', 'Teens']::text[], 'One week', 'A pause at the table feels, to a socially anxious client, like a verdict arriving in real time. The page asks what they do when a silence falls (talk fast, check the phone, leave for the kitchen), what they fear the silence means, and plans three silences this week they will let sit for a count of five, noticing the body and what happened next. Most silences end on their own, often with someone else speaking. Watch for the client who counts to five with their eyes down; part of the practice is staying present and visible.', '[{"id": "f0", "type": "textarea", "label": "What I usually do the moment a silence falls:"}, {"id": "f1", "type": "textarea", "label": "What I am afraid a silence means about me:"}, {"id": "f2", "type": "textarea", "label": "Three conversations this week where I will let a pause sit for a count of five:"}, {"id": "f3", "type": "textarea", "label": "What my body did during the count, and what happened when it ended:"}, {"id": "f4", "type": "textarea", "label": "What the silence turned out to mean, as far as I could tell:"}]'::jsonb, array['social anxiety', 'willingness', 'acceptance']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('give-skills-in-a-kitchen-full-of-in-laws-card', 'GIVE Skills in a Kitchen Full of In-Laws Card', 'dbt'::resource_kind, 'A DBT GIVE card for the client who is handed a peeler in a crowded kitchen of relatives they barely know.', 'Use it to give a client a gentle, interested, easy-mannered way to be in the kitchen without a script for every line.', array['Adults']::text[], '15 minutes before the gathering', 'A kitchen full of a partner''s relatives is a social test with no exit and knives on the counter. GIVE (Gentle, act Interested, Validate, Easy manner) turns it into four small jobs: a gentle face and tone, one interested question about the dish or the cook, something to validate (this looks like a lot of work), and a light manner that lets a joke land. The card plans each and names the task the client will ask for so their hands have a job. Watch for the client who plans to hide in the dish pit; a task near the conversation is better than one far from it.', '[{"id": "f0", "type": "textarea", "label": "Gentle: how I will keep my face and voice when I walk in:"}, {"id": "f1", "type": "textarea", "label": "Interested: one question I can ask about the food or the cook:"}, {"id": "f2", "type": "textarea", "label": "Validate: something true I can acknowledge about the work going on:"}, {"id": "f3", "type": "textarea", "label": "Easy manner: a light thing I can say or do when it gets tense:"}, {"id": "f4", "type": "textarea", "label": "The task I will ask for so my hands have a job near the conversation:"}, {"id": "f5", "type": "textarea", "label": "The signal I give my partner if I need five minutes:"}]'::jsonb, array['social anxiety', 'GIVE', 'interpersonal effectiveness']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('one-sentence-table-toast-rounds-game', 'One Sentence Table Toast Rounds Game', 'game'::resource_kind, 'A group game in which each player gives a one-sentence toast to the person beside them, with the group raising glasses of water each time.', 'Use it to give a group brief, structured practice at being the center of attention for exactly one sentence.', array['Groups', 'Teens']::text[], '20 minutes', 'Rules: sit around a table with glasses of water. Going clockwise, each player stands, says one sentence of toast to the person on their left (something true they appreciate), and the group raises glasses and says their name. No preamble, no apology, one sentence. Round two: the toast is to yourself. Debrief: what the body did while standing, what was harder, toasting someone or being toasted, and what the group noticed about members who rushed. Watch for the member who sits through their turn; offer to stand with them.', '[{"id": "f0", "type": "textarea", "label": "The toast I gave, in the words I used:"}, {"id": "f1", "type": "textarea", "label": "What my body did between standing up and finishing the sentence:"}, {"id": "f2", "type": "textarea", "label": "The toast I received, and what I did with it:"}, {"id": "f3", "type": "textarea", "label": "Harder: toasting someone else, being toasted, or toasting myself? Why:"}, {"id": "f4", "type": "textarea", "label": "Where in my week I could say one sentence out loud to a group:"}]'::jsonb, array['social anxiety', 'group', 'exposure']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('their-empty-seat-at-the-holiday-table-decision-sheet', 'Their Empty Seat at the Holiday Table Decision Sheet', 'worksheet'::resource_kind, 'A decision sheet for the family facing the first holiday meal with a seat that used to be someone''s.', 'Use it to help a client decide, before the day, what the seat and the place setting will be, and who needs to know.', array['Adults']::text[], '20 minutes before the holiday', 'The seat is the question nobody asks until everyone is standing around the table. The sheet lays out the options (leave it empty, set a place, put a photo or candle there, rearrange the table, sit someone new in it), what each one would mean to the client and to the others, who should be asked, and what they will say to a guest who does not know. There is no right answer; the point is a decision made on purpose. Watch for the client who decides alone for a whole family; add who else needs a say.', '[{"id": "f0", "type": "textarea", "label": "The options we have for the seat, and what each would mean to me:"}, {"id": "f1", "type": "textarea", "label": "What each would mean to the others at the table, as far as I know:"}, {"id": "f2", "type": "textarea", "label": "Who needs to be asked before we decide:"}, {"id": "f3", "type": "textarea", "label": "What we are choosing, and why:"}, {"id": "f4", "type": "textarea", "label": "What I will say if a guest asks about it or sits there:"}, {"id": "f5", "type": "textarea", "label": "What I will do for myself if the seat gets to me during the meal:"}]'::jsonb, array['grief and loss', 'decisions', 'family']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('laughing-at-dinner-means-i-have-forgotten-them-sheet', 'Laughing at Dinner Means I Have Forgotten Them Sheet', 'cbt'::resource_kind, 'A CBT sheet for the grieving client whose first laugh at a holiday meal is followed by a wave of guilt.', 'Use it to examine the rule that joy is disloyalty and let the laugh and the loss sit at the same table.', array['Adults', 'Teens']::text[], '20 minutes', 'A laugh in the first season after a death often arrives with a rule attached: if I can laugh, I have forgotten them. The sheet records the moment, the guilt thought, where the rule came from, what the person who died would have said about the laugh, and the evidence that the client remembers them (which is the grief itself). Then it asks what grieving and laughing in one evening says about the client. Watch for the client whose family enforces the rule; that is a different sheet, and a conversation to plan.', '[{"id": "f0", "type": "textarea", "label": "The moment I laughed, and what I was laughing at:"}, {"id": "f1", "type": "textarea", "label": "The thought that followed, word for word:"}, {"id": "f2", "type": "textarea", "label": "Where the rule that joy means forgetting came from:"}, {"id": "f3", "type": "textarea", "label": "What they would have said if they had seen me laugh:"}, {"id": "f4", "type": "textarea", "label": "Evidence that I have not forgotten them, including the guilt itself:"}, {"id": "f5", "type": "textarea", "label": "What laughing and grieving in one evening says about me:"}]'::jsonb, array['grief and loss', 'guilt', 'thinking traps']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('grief-as-a-guest-who-comes-to-every-holiday-page', 'Grief as a Guest Who Comes to Every Holiday Page', 'act'::resource_kind, 'An ACT acceptance page in which grief is a guest who arrives for every holiday, uninvited but expected, and gets a seat.', 'Use it to help a client stop bracing against grief''s arrival and plan how to host it alongside everyone else.', array['Adults', 'Teens']::text[], '15 minutes before the holiday', 'Grief comes to the holidays whether or not it is on the list, and the client who spends the day keeping it out spends the day at the door. The page asks what the guest brings (which memories, which moments it tends to arrive), where it will sit, what the client will do when it arrives (a step outside, a story told aloud, a hand on a photo), and who else at the table knows the guest is coming. Hosting grief is not the same as the day being about it. Watch for the client who plans to seat the guest in another room; ask what the day would be if it stayed.', '[{"id": "f0", "type": "textarea", "label": "When the guest tends to arrive during a holiday, and what it brings:"}, {"id": "f1", "type": "textarea", "label": "Where I will give it a seat, in plain terms (a moment, a toast, a photo, a walk):"}, {"id": "f2", "type": "textarea", "label": "What I will do when it arrives, so I am not standing at the door all day:"}, {"id": "f3", "type": "textarea", "label": "Who else at the table knows the guest is coming:"}, {"id": "f4", "type": "textarea", "label": "What I want the rest of the day to hold alongside it:"}]'::jsonb, array['grief and loss', 'acceptance', 'metaphor']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-of-the-first-holiday-without-them-card', 'Radical Acceptance of the First Holiday Without Them Card', 'dbt'::resource_kind, 'A DBT radical-acceptance card for the client approaching a first holiday after a death and fighting the fact of it hour by hour.', 'Use it to practice turning toward the reality of the day in small, repeated moments, with the pain that comes with it.', array['Adults']::text[], 'One holiday, then as needed', 'Radical acceptance does not mean approval; it means stopping the fight with what is true so the pain is grief instead of grief plus struggle. The card names the facts the client is fighting (they are not here, the day will happen without them), the ways the fight shows up (refusing plans, numbing, rage at the calendar), an acceptance statement in their own words, and a body practice (willing hands, a long out-breath) for the moments the fight returns. Watch for the client who hears acceptance as being asked to be fine; the card is about the fight, not the sadness.', '[{"id": "f0", "type": "textarea", "label": "The facts I am fighting about this holiday:"}, {"id": "f1", "type": "textarea", "label": "How the fight shows up in me (plans refused, numbing, anger at the day itself):"}, {"id": "f2", "type": "textarea", "label": "My acceptance statement, in my own words, said as many times as it takes:"}, {"id": "f3", "type": "textarea", "label": "The body practice I will use when the fight returns:"}, {"id": "f4", "type": "textarea", "label": "What I will do on the day that is for me, and what I will do that is for them:"}]'::jsonb, array['grief and loss', 'radical acceptance', 'core DBT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('memory-leaf-thankful-tree-craft', 'Memory Leaf Thankful Tree Craft', 'kids'::resource_kind, 'A craft in which a child adds paper leaves to a drawn tree, some with memories of someone who died and some with good things now.', 'Use it to let a child keep a person present at a holiday in a way they can hold, with the parent adding leaves too.', array['Children']::text[], '30 minutes, then through the season', 'A bare tree drawn on a large sheet and a stack of paper leaves let a child put memories where everyone can see them. Some leaves hold a memory of the person who died (what they cooked, a joke, a song); other leaves hold something the child is glad about now. The parent adds their own leaves and says the person''s name out loud, which gives the child permission. Keep the tree up through the season and add leaves as they come. Watch for the child who only adds now leaves; add a memory leaf yourself and leave it at that.', '[{"id": "f0", "type": "textarea", "label": "A memory of them I put on a leaf:"}, {"id": "f1", "type": "textarea", "label": "Something I am glad about right now that I put on a leaf:"}, {"id": "f2", "type": "textarea", "label": "A leaf my grown-up added, and what it said:"}, {"id": "f3", "type": "textarea", "label": "What it was like to hear their name said out loud:"}, {"id": "f4", "type": "textarea", "label": "Where our tree is, and when we will add more leaves:"}]'::jsonb, array['grief and loss', 'children', 'craft']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('sibling-who-keeps-score-of-favors-ledger-sheet', 'Sibling Who Keeps Score of Favors Ledger Sheet', 'worksheet'::resource_kind, 'A worksheet for the client in a sibling relationship run as a ledger of favors owed, where every ask comes with a tally.', 'Use it to lay the ledger out, see what the client is actually keeping score of and decide what they want instead of a balanced book.', array['Adults']::text[], '30 minutes', 'Some sibling relationships run on an invisible ledger: who drove whom, who hosted, who called first. The sheet makes it visible: what the client believes they are owed, what the sibling believes, what the score-keeping costs them both, and what they actually want from the relationship (usually not a balanced book). Then one move that is not a tally: an ask without a reminder, or a gift without a note. Watch for the client who wants to use the sheet to prove they are ahead; the sheet is for retiring the ledger, not auditing it.', '[{"id": "f0", "type": "textarea", "label": "What I believe my sibling owes me, listed as honestly as I can:"}, {"id": "f1", "type": "textarea", "label": "What my sibling probably believes I owe them:"}, {"id": "f2", "type": "textarea", "label": "What keeping score costs me, and what it costs us:"}, {"id": "f3", "type": "textarea", "label": "What I actually want from this relationship, apart from fairness:"}, {"id": "f4", "type": "textarea", "label": "One thing I will do this month that is not a tally (an ask without a reminder, a gift without a note):"}, {"id": "f5", "type": "textarea", "label": "What I will say to myself when the urge to count returns:"}]'::jsonb, array['relationship issues', 'family', 'fairness']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('not-tagged-in-the-group-photo-means-i-am-out-thought-record', 'Not Tagged in the Group Photo Means I Am Out Thought Record', 'cbt'::resource_kind, 'A thought record for the moment a client sees a friends'' photo online without them in it, or untagged, and concludes they have been dropped.', 'Use it to catch the hot thought, weigh the evidence and decide what, if anything, the client will do about the friendship.', array['Adults', 'Teens']::text[], '20 minutes', 'A group photo without them is instant evidence of exclusion for a client already uncertain of their place. The thought record takes the situation, the hot thought, the emotion and its strength, evidence for and against (how the plans were made, who else was missing, when they last saw these friends), and a balanced thought. Then a choice: ask a friend directly, make a plan, or let it go. Watch for the client who gathers evidence by scrolling for an hour; the record asks for what they know, not what they can find.', '[{"id": "f0", "type": "textarea", "label": "What I saw, and where:"}, {"id": "f1", "type": "textarea", "label": "The hot thought, word for word:"}, {"id": "f2", "type": "textarea", "label": "The feeling and how strong it was, 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "Evidence that supports the thought:"}, {"id": "f4", "type": "textarea", "label": "Evidence against it (how plans were made, who else was missing, when I last saw them):"}, {"id": "f5", "type": "textarea", "label": "A balanced thought, and what I will do: ask, make a plan, or let it go:"}]'::jsonb, array['relationship issues', 'mind reading', 'thought record']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('values-when-the-group-chat-goes-quiet-on-me-page', 'Values When the Group Chat Goes Quiet on Me Page', 'act'::resource_kind, 'An ACT values page for the client whose message landed in a busy group chat and got no reply, and who is choosing how to show up next.', 'Use it to move a client from waiting for a reply to acting on what kind of friend they want to be.', array['Adults', 'Teens']::text[], '15 minutes', 'A quiet group chat gives a client hours to compose a story about their place in it. The page asks what kind of friend they want to be, regardless of reply counts, what that friend would do next (nothing, a direct message to one person, a new plan), what they are willing to feel to do it (exposed, needy, uncool), and what they will do with the waiting. The reply is not in their hands; the next move is. Watch for the client who chooses silence as a value; ask whether it is a value or a protection.', '[{"id": "f0", "type": "textarea", "label": "What kind of friend I want to be, in my own words:"}, {"id": "f1", "type": "textarea", "label": "What that friend would do next in this chat, or outside it:"}, {"id": "f2", "type": "textarea", "label": "What I am willing to feel to do it:"}, {"id": "f3", "type": "textarea", "label": "What I will do with the waiting, instead of refreshing:"}, {"id": "f4", "type": "textarea", "label": "One move I will make today that fits the friend I want to be:"}]'::jsonb, array['relationship issues', 'values', 'connection']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('dear-man-splitting-the-group-dinner-bill-fairly-card', 'DEAR MAN Splitting the Group Dinner Bill Fairly Card', 'dbt'::resource_kind, 'A DBT DEAR MAN card for the friend who always ends up covering more than their share of the group check and never says so.', 'Use it to script a clear, calm request about money at the table before resentment chooses the words.', array['Adults', 'Teens']::text[], '15 minutes', 'Money at the end of a group dinner is a small, repeated moment where the client swallows an unfairness and then stews on the way home. DEAR MAN scripts the alternative: describe (the check came and we split it evenly), express (I feel uncomfortable paying for drinks I did not have), assert (can we pay for what we each ordered), reinforce (it will be quicker and nobody has to do math), stay mindful when someone jokes, appear confident, and negotiate (a rounding rule). Rehearse the Assert line until it is boring. Watch for the client who adds ''but it is fine'' at the end; cut it.', '[{"id": "f0", "type": "textarea", "label": "Describe: the facts of how the bill usually gets split:"}, {"id": "f1", "type": "textarea", "label": "Express: how I feel about it, as a feeling:"}, {"id": "f2", "type": "textarea", "label": "Assert: exactly what I am asking the group to do:"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what the group gets from the new way:"}, {"id": "f4", "type": "textarea", "label": "Mindful and confident: what I will do when someone jokes or pushes back:"}, {"id": "f5", "type": "textarea", "label": "Negotiate: what I am willing to accept instead (a rounding rule, an app, taking turns):"}]'::jsonb, array['relationship issues', 'DEAR MAN', 'money']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('past-argument-brought-up-at-dinner-repair-plan-for-partners', 'Past Argument Brought Up at Dinner Repair Plan for Partners', 'couples'::resource_kind, 'A couples repair plan for the moment one partner brings up an old fight in front of family at a holiday meal.', 'Use it to let both partners name what happened, what it meant, and agree how old arguments are handled in public from now on.', array['Couples']::text[], 'One session', 'An old argument aired in front of relatives is a double injury: the original wound and the public one. Each partner writes what happened from their seat, what they felt and what they think the other meant, then the couple works out the repair (what is said, by whom, in private), a rule for old arguments in company (none at the table, a signal, a time to talk later), and what each needs to feel the matter is actually closed. Watch for the partner who insists it was a joke; the sheet asks them to write what it felt like from the other chair.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what happened at the table, from my seat, and what I felt:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what happened at the table, from my seat, and what I felt:"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I think you meant, and what I needed instead:"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I think you meant, and what I needed instead:"}, {"id": "f4", "type": "textarea", "label": "Our repair: what is said, by whom, and where:"}, {"id": "f5", "type": "textarea", "label": "Our rule for old arguments in company from now on:"}, {"id": "f6", "type": "textarea", "label": "What each of us needs to call the matter closed:"}]'::jsonb, array['relationship issues', 'couples', 'repair']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('sleeping-over-at-a-relatives-house-comfort-plan-sheet', 'Sleeping Over at a Relative''s House Comfort Plan Sheet', 'worksheet'::resource_kind, 'A safety-and-comfort plan for a client staying overnight at a relative''s house over the holidays when sleeping away from home is hard.', 'Use it to plan the room, the door, the exits and the people, so the client''s nights away rest on choices they made in advance.', array['Adults', 'Teens']::text[], '20 minutes before the trip', 'Sleeping in someone else''s house asks a client with a history of abuse to give up the controls they have built at home. The sheet restores some of them in advance: which room and whether the door locks or can be propped, what they bring from home for the night (a light, a sound, a familiar blanket), who in the house knows they may need space, an alternative (a hotel, a friend''s couch) they are allowed to use without explanation, and a grounding routine for 2 a.m. The plan is about this trip, not the past. Watch for the client who feels silly planning; the plan is what makes the trip possible.', '[{"id": "f0", "type": "textarea", "label": "The room I will sleep in, and what I know about the door:"}, {"id": "f1", "type": "textarea", "label": "What I will bring from home for the night (a light, a sound, a blanket, a lock):"}, {"id": "f2", "type": "textarea", "label": "Who in the house knows I may need space, and what I have told them:"}, {"id": "f3", "type": "textarea", "label": "My alternative if I need to leave, and how I would get there:"}, {"id": "f4", "type": "textarea", "label": "My routine if I wake at 2 a.m. (grounding, a text, a light on):"}, {"id": "f5", "type": "textarea", "label": "One kind thing I will say to myself for having made this plan:"}]'::jsonb, array['sexual abuse', 'safety', 'planning']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('freezing-means-i-allowed-it-gentle-check-sheet', 'Freezing Means I Allowed It Gentle Check Sheet', 'cbt'::resource_kind, 'A gentle CBT sheet for the belief that going still during what happened was the same as agreeing to it.', 'Use it, in session, to examine the self-blame around freezing without asking the client to revisit what happened.', array['Adults', 'Teens']::text[], 'One session', 'Freezing is one of the body''s automatic responses to threat, and many clients carry it as proof they let it happen. The sheet stays with the belief, not the event: the belief in their words, what they know about how bodies respond to fear, what they would say to a friend whose body went still, and who the responsibility actually belongs to. It is done in session with you, never as homework, and the client decides how much to write. If the client is at risk, 988 (call or text) is on the sheet and you make a plan together before the session ends. Watch the pacing; stop before they are flooded.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my own words, without describing what happened:"}, {"id": "f1", "type": "textarea", "label": "What I know about how bodies respond to fear and threat:"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend who told me their body went still:"}, {"id": "f3", "type": "textarea", "label": "Who the responsibility for what happened actually belongs to:"}, {"id": "f4", "type": "textarea", "label": "What I feel right now, 0 to 10, and what I need in this room:"}, {"id": "f5", "type": "textarea", "label": "If I ever feel unsafe with myself, I can call or text 988. Who else I can reach:"}]'::jsonb, array['sexual abuse', 'self-blame', 'stabilizing']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('values-for-the-boundaries-i-keep-this-weekend-page', 'Values for the Boundaries I Keep This Weekend Page', 'act'::resource_kind, 'An ACT values page for the holiday weekend, connecting each boundary the client plans to hold to what matters to them now.', 'Use it to help a client set limits with relatives from their values rather than from fear or apology.', array['Adults', 'Teens']::text[], '15 minutes before the weekend', 'Holiday weekends are dense with touch, proximity and questions, and a client with a history of abuse often holds limits while feeling they owe an explanation. The page lists the boundaries they plan to keep (who they will not be alone with, how they greet people, what they will not discuss, when they leave), the value under each (safety, honesty, dignity, choice), and the short line that holds the boundary without a reason. Values make the limits theirs. Watch for the client who justifies every boundary; the page is where they stop having to.', '[{"id": "f0", "type": "textarea", "label": "The boundaries I plan to keep this weekend, listed plainly:"}, {"id": "f1", "type": "textarea", "label": "The value under each one (safety, honesty, dignity, choice, rest):"}, {"id": "f2", "type": "textarea", "label": "The short line I will use to hold each, without giving a reason:"}, {"id": "f3", "type": "textarea", "label": "Who I can stand near when a boundary gets tested:"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself if someone is disappointed:"}, {"id": "f5", "type": "textarea", "label": "One thing I will do this weekend because I want to, not because I was asked:"}]'::jsonb, array['sexual abuse', 'values', 'boundaries']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('grounding-through-the-feet-on-the-kitchen-floor-card', 'Grounding Through the Feet on the Kitchen Floor Card', 'dbt'::resource_kind, 'A DBT grounding card that uses the soles of the feet on a hard floor to bring a client back into the present room.', 'Use it to give a client a grounding move they can do while standing at a counter in a crowded house, unnoticed.', array['Adults', 'Teens']::text[], 'Three minutes, as needed', 'When a kitchen full of people starts to feel far away, the floor is the nearest solid thing. The card has the client press both feet down, notice the pressure in heels and toes, shift weight slowly side to side, feel the temperature of the floor through socks or shoes, and name the room (the date, the house, who is here). It can be done at a sink or a counter without anyone noticing. Practice on a calm day first. Watch for the client who holds their breath while pressing; add a long out-breath to the sequence.', '[{"id": "f0", "type": "textarea", "label": "Where I was standing, and what the floor felt like through my feet:"}, {"id": "f1", "type": "textarea", "label": "What I noticed as I shifted my weight side to side:"}, {"id": "f2", "type": "textarea", "label": "The things I named to myself about the room (date, house, who is here):"}, {"id": "f3", "type": "textarea", "label": "How far away things felt before, 0 to 10, and after three minutes:"}, {"id": "f4", "type": "textarea", "label": "Another floor in my week where I could practice this:"}]'::jsonb, array['sexual abuse', 'grounding', 'mindfulness']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('red-light-green-light-touch-rules-play', 'Red Light Green Light Touch Rules Play', 'kids'::resource_kind, 'A play in which a child uses a red and green paddle to show a parent which touches, hugs and tickles are okay and which are not.', 'Use it to give a young child a game for body rules and a parent clear practice at honoring a red light.', array['Children']::text[], '20 minutes', 'A paper plate colored green on one side and red on the other gives a child a way to answer before words come. The parent names ordinary situations (a high five, a hug from grandma, a tickle, someone asking to keep a secret about touching) and the child holds up red or green; the parent honors every red light out loud and practices stopping mid-tickle when red goes up. The child learns the paddle works and the parent learns to see it. If a child discloses anything during play, follow your reporting duties and stay calm and warm. Watch for the parent who argues with a red; red is red.', '[{"id": "f0", "type": "textarea", "label": "Touches I gave a green light to:"}, {"id": "f1", "type": "textarea", "label": "Touches I gave a red light to:"}, {"id": "f2", "type": "textarea", "label": "What my grown-up did when I held up red:"}, {"id": "f3", "type": "textarea", "label": "Who I can tell if someone does not stop at my red light:"}, {"id": "f4", "type": "textarea", "label": "Where I will keep my paddle:"}]'::jsonb, array['sexual abuse', 'children', 'safety']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('coping-skills-for-a-long-car-ride-sort-sheet', 'Coping Skills for a Long Car Ride Sort Sheet', 'worksheet'::resource_kind, 'A sort sheet for the hours in a car over the holidays, matching the client''s coping skills to a seat, a seatbelt and no privacy.', 'Use it to pre-sort which skills work in a moving car, which need a rest stop and which stay home.', array['Adults', 'Teens']::text[], '15 minutes before the trip', 'A long drive with family is a coping test with unusual constraints: no exit, limited movement, other people''s music. The sheet lists the client''s usual skills and sorts them into works in the car (a playlist, a grounding count, a text to a friend), needs a rest stop (a walk, cold water on the face), and stays home (a run, a bath). Then it adds a plan for the hour that is usually worst. Watch for the client who plans to white-knuckle the whole drive; the rest-stop column is the permission to ask for one.', '[{"id": "f0", "type": "textarea", "label": "My usual coping skills, listed:"}, {"id": "f1", "type": "textarea", "label": "Which ones work in a moving car with people around:"}, {"id": "f2", "type": "textarea", "label": "Which ones need a rest stop, and how I will ask for one:"}, {"id": "f3", "type": "textarea", "label": "Which ones stay home, and what replaces them:"}, {"id": "f4", "type": "textarea", "label": "The hour of the drive that is usually worst, and my plan for it:"}, {"id": "f5", "type": "textarea", "label": "What I will tell the driver, if anything, about my plan:"}]'::jsonb, array['coping skills', 'planning', 'travel']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('skills-only-work-for-other-people-belief-sheet', 'Skills Only Work for Other People Belief Sheet', 'cbt'::resource_kind, 'A CBT sheet for the client who has tried coping skills, decided they do not work for them specifically and stopped.', 'Use it to look at how the skills were tried, what was expected of them and whether the belief rests on fair tests.', array['Adults', 'Teens']::text[], '20 minutes', 'A client who says skills do not work for me has usually tried a few, once each, in the hardest moment, expecting them to erase the feeling. The sheet names the belief, lists each skill tried with how many times and when, what they expected it to do versus what a skill can do (take the edge off, buy a minute), one skill that has ever helped even slightly, and a fair test for one skill this week (five times, on medium days). Watch for the client who uses the sheet to prove the belief; the fair test is the move.', '[{"id": "f0", "type": "textarea", "label": "The belief in my own words:"}, {"id": "f1", "type": "textarea", "label": "Each skill I have tried, how many times, and in what kind of moment:"}, {"id": "f2", "type": "textarea", "label": "What I expected a skill to do, and what a skill can realistically do:"}, {"id": "f3", "type": "textarea", "label": "One skill that has ever helped even a little, and when:"}, {"id": "f4", "type": "textarea", "label": "My fair test this week: which skill, how many times, on what kind of day:"}, {"id": "f5", "type": "textarea", "label": "What would count as it working:"}]'::jsonb, array['coping skills', 'core beliefs', 'predictions']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('coping-skill-as-a-spare-tire-in-the-trunk-page', 'Coping Skill as a Spare Tire in the Trunk Page', 'act'::resource_kind, 'An ACT page that treats a coping skill as a spare tire: not for every mile, but checked, inflated and ready for the flat.', 'Use it to help a client keep skills maintained and in reach rather than resenting them on good days.', array['Adults', 'Teens']::text[], '15 minutes, then one check a week', 'Clients often abandon skills on good days and then cannot find them in a crisis. The spare tire image reframes the skill as something you keep in good order without driving on it. The page asks which skills are in the trunk, when each was last checked (practiced on a calm day), which are flat, how they will keep one inflated this week, and what a flat would look like so they know when to pull over. Watch for the client with twelve spares and no practice; pick two.', '[{"id": "f0", "type": "textarea", "label": "The skills in my trunk right now:"}, {"id": "f1", "type": "textarea", "label": "When I last practiced each one on a calm day:"}, {"id": "f2", "type": "textarea", "label": "Which ones are flat, and which I am retiring:"}, {"id": "f3", "type": "textarea", "label": "The one or two I will keep inflated this week, and how:"}, {"id": "f4", "type": "textarea", "label": "What a flat looks like for me, so I know when to pull over and get the spare:"}]'::jsonb, array['coping skills', 'metaphor', 'committed action']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('improve-the-moment-stuck-in-holiday-traffic-card', 'IMPROVE the Moment Stuck in Holiday Traffic Card', 'dbt'::resource_kind, 'A DBT IMPROVE card for the hours in holiday traffic when the client cannot change the road and can change the moment.', 'Use it to give a client seven ways to make a stuck hour bearable without pretending it is pleasant.', array['Adults', 'Teens']::text[], '15 minutes before the trip, then as needed', 'IMPROVE (Imagery, Meaning, Prayer, Relaxation, One thing in the moment, Vacation, Encouragement) is built for a situation that cannot be changed, which describes a highway at a standstill on the Wednesday before a holiday. The card asks for one option under each that works behind a wheel or in a passenger seat: a place to picture, what the drive is for, a word or phrase, a shoulder drop, the one thing to attend to, a two-minute mental vacation, and the sentence they would say to a friend in this car. Watch for the client whose Encouragement is sarcastic; rewrite it kindly.', '[{"id": "f0", "type": "textarea", "label": "Imagery: the place I will picture at the next full stop:"}, {"id": "f1", "type": "textarea", "label": "Meaning: what this drive is for:"}, {"id": "f2", "type": "textarea", "label": "Prayer or a phrase: the words I will say under my breath:"}, {"id": "f3", "type": "textarea", "label": "Relaxation: the one body move I can do behind the wheel or in my seat:"}, {"id": "f4", "type": "textarea", "label": "One thing in the moment: what I will give my full attention to for one minute:"}, {"id": "f5", "type": "textarea", "label": "Vacation: my two-minute mental break, and when I will take it:"}, {"id": "f6", "type": "textarea", "label": "Encouragement: the sentence I would say to a friend in this car:"}]'::jsonb, array['coping skills', 'IMPROVE', 'distress tolerance']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('coping-skill-pictionary-draw-the-skill-game', 'Coping Skill Pictionary Draw the Skill Game', 'game'::resource_kind, 'A group game in which players draw a coping skill on a whiteboard, no words allowed, while their team guesses it against the clock.', 'Use it to get a group naming, picturing and laughing about their skills until the names come easily under pressure.', array['Groups', 'Teens', 'Children']::text[], '25 minutes', 'Rules: write coping skills on slips (paced breathing, cold water, call a friend, take a walk, name five things you can see). Teams alternate; a drawer pulls a slip and has sixty seconds to draw it with no letters or numbers while their team guesses. A correct guess scores, and the team must then say when they would use it. Debrief: which skills were easy to draw and which impossible, which ones nobody recognized, and which skill each player wants to add to their own list. Watch for the member who refuses to draw; let them be the timer, then drawer next round.', '[{"id": "f0", "type": "textarea", "label": "The skill I drew, and how long it took my team to guess:"}, {"id": "f1", "type": "textarea", "label": "The skill that was hardest to draw, and why:"}, {"id": "f2", "type": "textarea", "label": "A skill I did not recognize until someone explained it:"}, {"id": "f3", "type": "textarea", "label": "When my team said we would use the skill we guessed:"}, {"id": "f4", "type": "textarea", "label": "One skill from the game I will try this week:"}]'::jsonb, array['coping skills', 'group', 'game']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('driving-over-the-long-highway-bridge-step-plan-sheet', 'Driving Over the Long Highway Bridge Step Plan Sheet', 'worksheet'::resource_kind, 'A stepped plan for the client whose holiday route crosses a long bridge they have been driving miles to avoid.', 'Use it to build a ladder from looking at the bridge to driving it alone, with a step the client can take this week.', array['Adults']::text[], '20 minutes, then several weeks', 'Bridge avoidance grows quietly; the detour becomes the route and the fear is never tested. The sheet builds a ladder: looking at photos, driving to the on-ramp and turning around, riding across as a passenger, driving across with a passenger, driving across alone, then the long bridge on the holiday route. Each step gets a predicted and an actual fear rating and a note on what happened. The client picks the step for this week, and stays on it until it is boring. Watch for the client who jumps to the top step to get it over with; the ladder is the point.', '[{"id": "f0", "type": "textarea", "label": "The bridge I avoid, and the detour I take instead:"}, {"id": "f1", "type": "textarea", "label": "My ladder, from easiest to hardest, in six or seven steps:"}, {"id": "f2", "type": "textarea", "label": "The step I am taking this week, and when:"}, {"id": "f3", "type": "textarea", "label": "Predicted fear for that step (0 to 10), and the actual fear when I did it:"}, {"id": "f4", "type": "textarea", "label": "What happened on the bridge, in plain facts:"}, {"id": "f5", "type": "textarea", "label": "What I will tell myself at the on-ramp:"}]'::jsonb, array['phobias', 'hierarchy', 'exposure']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('the-escalator-will-catch-my-shoe-prediction-sheet', 'The Escalator Will Catch My Shoe Prediction Sheet', 'cbt'::resource_kind, 'A CBT prediction sheet for the mall escalator the client takes the long way around, afraid of being pulled in at the top.', 'Use it to write the prediction, test it on a real escalator and compare the result with the fear.', array['Adults', 'Teens', 'Children']::text[], '20 minutes, then one trip', 'Escalator fear usually rests on a vivid prediction (my shoe gets caught, I fall, everyone sees) that has never been tested because the stairs are right there. The sheet writes the prediction and its certainty, what the client has actually seen happen to the hundreds of people who ride them, a plan to ride one (hand on the rail, step on with the right foot, step off when the step flattens), and the result. For a child, the parent rides beside them and goes first. Watch for the client who rides it once and declares victory; schedule three more.', '[{"id": "f0", "type": "textarea", "label": "My prediction about what will happen on the escalator, and how sure I am (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "What I have actually seen happen to the people who ride them:"}, {"id": "f2", "type": "textarea", "label": "My plan for riding one (hand on the rail, which foot, when I step off):"}, {"id": "f3", "type": "textarea", "label": "What happened when I rode it:"}, {"id": "f4", "type": "textarea", "label": "How sure I am of the prediction now:"}, {"id": "f5", "type": "textarea", "label": "The next escalator I will ride, and when:"}]'::jsonb, array['phobias', 'predictions', 'behavioral experiment']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('willing-to-stand-on-the-balcony-rail-side-page', 'Willing to Stand on the Balcony Rail Side Page', 'act'::resource_kind, 'An ACT willingness page for the client who stays by the wall at any height and misses the view, the party and the fresh air.', 'Use it to connect standing nearer the rail to a value and make room for the body''s alarm while doing it.', array['Adults', 'Teens']::text[], '15 minutes, then as needed', 'A fear of heights keeps the client against the back wall of every balcony, stadium and overlook. The page asks what they miss from the wall, the value that would carry them a step closer (being with people, seeing the view, not being ruled by it), what the body will do when they move (and that it is allowed to), how close they are willing to stand today, and what they will notice when they get there. Willingness is a step, not the rail itself. Watch for the client who leans over to prove it; a steady stand is the practice.', '[{"id": "f0", "type": "textarea", "label": "What I miss by staying against the wall:"}, {"id": "f1", "type": "textarea", "label": "The value that would carry me one step closer:"}, {"id": "f2", "type": "textarea", "label": "What my body will do when I move, and what I will let it do:"}, {"id": "f3", "type": "textarea", "label": "How close I am willing to stand today, measured in steps from the wall:"}, {"id": "f4", "type": "textarea", "label": "What I noticed from there that I could not see from the wall:"}, {"id": "f5", "type": "textarea", "label": "The next balcony or overlook in my life, and my step for it:"}]'::jsonb, array['phobias', 'willingness', 'values']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('cope-ahead-imagery-for-the-mri-tube-card', 'Cope Ahead Imagery for the MRI Tube Card', 'dbt'::resource_kind, 'A DBT cope-ahead card for the client with a scan booked who cannot imagine lying still in the tube for forty minutes.', 'Use it to rehearse the whole scan in imagery, skills included, so the day is a second run rather than a first.', array['Adults', 'Teens']::text[], '30 minutes, repeated before the scan', 'An enclosed scanner is loud, tight and long, and the client''s imagination has already run it badly a dozen times. Cope ahead runs it well on purpose: the client describes the day in detail (the gown, the table, the sounds), names the hardest moment, picks the skills (paced breathing, a counting pattern, a mantra, eyes closed before entering), and rehearses the whole thing in imagery including the end. Ask them what they can request (music, a mirror, a hand squeeze signal). Watch for the client who rehearses stopping the scan; include the exit as a choice, then rehearse staying.', '[{"id": "f0", "type": "textarea", "label": "The day in detail, from arriving to lying down:"}, {"id": "f1", "type": "textarea", "label": "The hardest moment I expect, and what my body will do:"}, {"id": "f2", "type": "textarea", "label": "The skills I will use inside (breath count, phrase, eyes closed, music):"}, {"id": "f3", "type": "textarea", "label": "What I can ask the technician for before I go in:"}, {"id": "f4", "type": "textarea", "label": "The whole scan rehearsed in my mind, through to sitting up at the end:"}, {"id": "f5", "type": "textarea", "label": "What I will do for myself afterward:"}]'::jsonb, array['phobias', 'cope ahead', 'core DBT']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('brave-mouse-visits-the-dark-basement-play', 'Brave Mouse Visits the Dark Basement Play', 'kids'::resource_kind, 'A play in which a child moves a toy mouse down a dark basement staircase one step at a time, with a parent at the top.', 'Use it to let a child practice approaching the dark by proxy, deciding each step, with the parent close but not leading.', array['Children']::text[], '20 minutes, then a few evenings', 'A small toy mouse, a flashlight and a real staircase let a child take the fear of the dark one step at a time without being the one in the dark. The child decides how far the mouse goes tonight, narrates what the mouse feels and what it notices (a shelf, a smell, a light switch), and brings it back up as a hero. The parent stays at the top of the stairs, keeps the flashlight ready, and asks the mouse questions rather than pushing. Each evening the mouse goes one step farther. Watch for the parent who carries the mouse down; the child decides the step.', '[{"id": "f0", "type": "textarea", "label": "How many steps my brave mouse went tonight:"}, {"id": "f1", "type": "textarea", "label": "What the mouse noticed in the dark that was not scary:"}, {"id": "f2", "type": "textarea", "label": "What the mouse felt in its tummy, and what it did about it:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up asked the mouse from the top of the stairs:"}, {"id": "f4", "type": "textarea", "label": "How far the mouse will go tomorrow:"}]'::jsonb, array['phobias', 'children', 'play']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('family-comments-about-my-looks-reply-plan-sheet', 'Family Comments About My Looks Reply Plan Sheet', 'worksheet'::resource_kind, 'A planning sheet for the relatives who greet the client with a comment about how they look, and the replies that stop it.', 'Use it to script short, firm replies and a change of subject so the client is not stunned into silence at the door.', array['Adults', 'Teens']::text[], '15 minutes before the gathering', 'Some relatives open with a remark about the client''s appearance, and the client spends the evening rehearsing what they should have said. The sheet names who, their usual line, the client''s one-sentence reply (I would rather talk about anything else; let''s not do looks this year), a change of subject ready to go, an ally who will back it up, and what the client will do with the feeling afterward. The reply should be short enough to say with a coat still on. Watch for the client who plans a lecture; a sentence and a subject change land better.', '[{"id": "f0", "type": "textarea", "label": "Who tends to comment, and what they usually say:"}, {"id": "f1", "type": "textarea", "label": "My one-sentence reply, said with my coat still on:"}, {"id": "f2", "type": "textarea", "label": "The subject I will change to:"}, {"id": "f3", "type": "textarea", "label": "The ally who will back me up, and what I have asked them to do:"}, {"id": "f4", "type": "textarea", "label": "What I will do with the feeling afterward, instead of carrying it to the table:"}, {"id": "f5", "type": "textarea", "label": "What I will say to myself in the car about having held the line:"}]'::jsonb, array['body image', 'assertiveness', 'planning']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('old-photos-prove-i-looked-better-then-comparison-sheet', 'Old Photos Prove I Looked Better Then Comparison Sheet', 'cbt'::resource_kind, 'A CBT sheet for the client who looks at old photos and concludes their current self is a decline.', 'Use it to catch the then-versus-now comparison and look at what the old photo and the client''s memory leave out.', array['Adults', 'Teens']::text[], '20 minutes', 'Old photos are selected twice, once by whoever took them and again by the client''s memory. The sheet names the comparison thought, what the photo was chosen for, what the client actually felt about their appearance at the time (usually the same dissatisfaction), what has been added to their life since, and what they would say to a younger self who disliked that photo. It never asks about size, shape or any part of the body. Watch for the client who wants to ''get back'' to the photo; redirect to what they want from this year, not that one.', '[{"id": "f0", "type": "textarea", "label": "The photo, and the thought that arrived with it:"}, {"id": "f1", "type": "textarea", "label": "Who chose or kept this photo, and why:"}, {"id": "f2", "type": "textarea", "label": "What I actually thought about how I looked at the time it was taken:"}, {"id": "f3", "type": "textarea", "label": "What has come into my life since that photo:"}, {"id": "f4", "type": "textarea", "label": "What I would say to the person in the photo about how they saw themselves:"}, {"id": "f5", "type": "textarea", "label": "What I want from this year that has nothing to do with a photo:"}]'::jsonb, array['body image', 'comparison', 'thinking traps']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('body-as-the-host-not-the-centerpiece-page', 'Body as the Host Not the Centerpiece Page', 'act'::resource_kind, 'An ACT values page in which the client''s body is the host of the gathering, there to carry, greet and serve, not the thing on display.', 'Use it to shift a client''s attention from how the body looks at an event to what it is for.', array['Adults', 'Teens']::text[], '15 minutes before the gathering', 'A client who dreads being seen at a gathering experiences their body as the centerpiece everyone is evaluating. The page recasts it as the host: the body that carries the dish, hugs the aunt, stands at the stove, laughs at the table. It asks what the body will do at the event, what the client values about those actions, where attention goes when it is on hosting rather than being seen, and one moment they will give their body a job. Watch for the client who turns hosting into hiding in the kitchen; the host also sits at the table.', '[{"id": "f0", "type": "textarea", "label": "What my body will do at this event (carry, greet, cook, hold, laugh):"}, {"id": "f1", "type": "textarea", "label": "What I value about those actions:"}, {"id": "f2", "type": "textarea", "label": "Where my attention goes when I am being seen, and where it goes when I am hosting:"}, {"id": "f3", "type": "textarea", "label": "One moment at the event I will give my body a job on purpose:"}, {"id": "f4", "type": "textarea", "label": "What I will notice about the evening if my body is the host and not the centerpiece:"}]'::jsonb, array['body image', 'values', 'metaphor']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-warm-socks-not-the-mirror-card', 'Mindfulness of Warm Socks Not the Mirror Card', 'dbt'::resource_kind, 'A DBT mindfulness card that moves attention from the mirror to the felt sense of warm socks, a sweater and a mug on a cold morning.', 'Use it to give a client a daily morning practice of inhabiting the body from the inside rather than inspecting it from the outside.', array['Adults', 'Teens']::text[], 'Five minutes daily for one week', 'Mornings for a client with body image distress start at the mirror and go downhill. The card moves the first five minutes to the felt body: warm socks going on, the weight and texture of a sweater, a mug warming the hands, the floor under the feet. It is observing and describing from the inside, without judging, and the mirror can wait. The log asks what they noticed and how the morning went from there. Watch for the client who does the five minutes in front of the mirror; move the socks to another room.', '[{"id": "f0", "type": "textarea", "label": "What I noticed putting on warm socks (temperature, texture, pressure):"}, {"id": "f1", "type": "textarea", "label": "What I noticed about the sweater, the mug, the floor:"}, {"id": "f2", "type": "textarea", "label": "Where my attention went when it left the body, and how I brought it back:"}, {"id": "f3", "type": "textarea", "label": "How long it was before I looked in a mirror, compared with usual:"}, {"id": "f4", "type": "textarea", "label": "How the rest of the morning went:"}]'::jsonb, array['body image', 'mindfulness', 'self-soothing']::text[], '2026-11-24T15:00:00+00:00'::timestamptz),
  ('getting-dressed-for-the-gathering-support-plan-for-partners', 'Getting Dressed for the Gathering Support Plan for Partners', 'couples'::resource_kind, 'A couples plan for the hour before a gathering when one partner struggles with getting dressed and the other does not know how to help.', 'Use it to let both partners agree on what helps, what hurts and what the supporting partner actually says in that hour.', array['Couples']::text[], '20 minutes before the event', 'The hour before a gathering is where body image distress surfaces at home, and the supporting partner usually reaches for reassurance that does not land. Each partner writes what that hour is like for them, then the couple agrees what the supporting partner says and does not say (no comments on appearance, good or bad, unless asked), what actually helps (a time check, a hand, picking the music, carrying the dish), the signal for needing a minute, and what happens if the struggling partner wants to stay home. Watch for the partner who promises compliments; write down what is wanted instead.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what the hour before a gathering is like for me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what that hour is like for me, and what I usually try:"}, {"id": "f2", "type": "textarea", "label": "What the supporting partner will say, and what they will not say about appearance:"}, {"id": "f3", "type": "textarea", "label": "What actually helps (a time check, music, a hand, carrying things):"}, {"id": "f4", "type": "textarea", "label": "The signal for needing a minute, and what happens then:"}, {"id": "f5", "type": "textarea", "label": "What we do if one of us wants to stay home at the last minute:"}]'::jsonb, array['body image', 'couples', 'support']::text[], '2026-11-24T15:00:00+00:00'::timestamptz)
